def _traits(entries):
    return [{"name": t.get("name",""), "text": entries_to_text(t.get("entries",[]))}
            for t in entries if isinstance(t, dict) and t.get("name")]

def _speed(r):
    sp = r.get("speed")
    return sp if isinstance(sp, int) else (sp or {}).get("walk", 30)

def build_races(raw):
    out, bases = [], {}
    for r in raw.get("race", []):
        if not is_phb(r): continue
        bases[r["name"]] = {"ability": r.get("ability", []), "speed": _speed(r), "traits": _traits(r.get("entries", []))}
        out.append({"name": r["name"], "ability": r.get("ability", []),
                    "size": "/".join(SIZE.get(s, s) for s in r.get("size", [])) or "Medium",
                    "speed": _speed(r), "traits": _traits(r.get("entries", []))})
    for s in raw.get("subrace", []):
        if not is_phb(s) or not s.get("name"): continue
        base = bases.get(s.get("raceName"), {})
        out.append({"name": f"{s.get('raceName','')} ({s['name']})",
                    "ability": (base.get("ability", []) or []) + (s.get("ability", []) or []),  # base + subrace
                    "size": "", "speed": base.get("speed", 30), "subraceOf": s.get("raceName"),
                    "traits": (base.get("traits", []) or []) + _traits(s.get("entries", []))})
    return out

