// ---- PHB content pickers (data baked in by build-data.py; null in the shareable app) ----
let PHB = null;
const ABKEYS = ["str","dex","con","int","wis","cha"];
const SKILL_KEY = {"acrobatics":"acrobatics","animal handling":"animal","arcana":"arcana",
  "athletics":"athletics","deception":"deception","history":"history","insight":"insight",
  "intimidation":"intimidation","investigation":"investigation","medicine":"medicine",
  "nature":"nature","perception":"perception","performance":"performance","persuasion":"persuasion",
  "religion":"religion","sleight of hand":"sleight","stealth":"stealth","survival":"survival"};
const esc = s => String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;");
const optTag = (v,label) => `<option value="${esc(v)}">${esc(label)}</option>`;
const findBy = (arr,n) => arr.find(x => x.name === n);

function populatePickers(){
  if(!PHB){ const c=$("phb-build"); if(c) c.style.display="none"; return; }
  $("phb-build").style.display = "";
  $("pick-race").innerHTML  = `<option value="">—</option>` + PHB.races.map(r=>optTag(r.name,r.name)).join("");
  $("pick-class").innerHTML = `<option value="">—</option>` + PHB.classes.map(c=>optTag(c.name,c.name)).join("");
  $("pick-bg").innerHTML    = `<option value="">—</option>` + PHB.backgrounds.map(b=>optTag(b.name,b.name)).join("");
  populateSubclass($("pick-class").value);
}
function populateSubclass(clsName){
  const sel=$("pick-subclass"); if(!sel || !PHB) return;
  const cls=findBy(PHB.classes,clsName), subs=cls?cls.subclasses:[];
  sel.innerHTML = `<option value="">${subs.length?esc(cls.subclassTitle||"Subclass"):"—"}</option>` + subs.map(s=>optTag(s.name,s.name)).join("");
  sel.disabled = !subs.length;
}
function setNote(s){ const el=$("build-note"); if(el) el.textContent = s||""; }

function applyRace(name){
  ABKEYS.forEach(k => racialVals[k]=0);            // race owns racial bonuses
  const r = PHB && findBy(PHB.races,name);
  if(r){
    $("race").value = name;
    let choose=null;
    (r.ability||[]).forEach(blk => Object.entries(blk).forEach(([k,v])=>{
      if(ABKEYS.includes(k) && typeof v==="number") racialVals[k]+=v; else if(k==="choose") choose=v;
    }));
    if(r.speed) $("speed").value = r.speed+" ft";
    if(r.traits && r.traits.length && !$("features").value.trim())
      $("features").value = r.traits.map(t=>`${t.name}. ${t.text}`).join("\n\n");
    const fixed = ABKEYS.filter(k=>racialVals[k]).map(k=>ABBR[k]+" +"+racialVals[k]).join(", ");
    setNote(`Applied ability bonuses: ${fixed||"none fixed"}.` +
            (choose?`\nAlso choose +${choose.amount||1} to ${choose.count} ability score(s) — set via +race.`:""));
  } else setNote("");
}
function applyClass(name){
  populateSubclass(name);
  const c = PHB && findBy(PHB.classes,name);
  if(c){
    const lvl = num($("level").value,1);
    $("classlevel").value = name+" "+lvl;
    ABKEYS.forEach(k=>{ const box=$("savep-"+k); if(box) box.checked = c.saves.includes(k); });
    if(c.hd) $("hitdice").value = lvl+"d"+c.hd;
    let n = `Saves: ${c.saves.map(s=>ABBR[s]).join(", ")} · Hit die d${c.hd}.`;
    if(c.skillChoose) n += `\nClass skills: choose ${c.skillChoose.count} from ${c.skillChoose.from.join(", ")}.`;
    if(c.casterAbility) n += `\nSpellcaster: ${ABBR[c.casterAbility]} (${c.casterProgression}).`;
    setNote(n);
  } else setNote("");
}
function applyBackground(name){
  const b = PHB && findBy(PHB.backgrounds,name);
  if(b){
    $("background").value = name;
    (b.skills||[]).forEach(s=>{ const key=SKILL_KEY[s], box=key&&$("skp-"+key); if(box) box.checked=true; });
    if(b.feature && b.feature.name){
      const line = `${b.feature.name} (${name}). ${b.feature.text}`;
      const t=$("proficiencies"); t.value = t.value.trim() ? t.value+"\n\n"+line : line;
    }
    let n = `Skill proficiencies: ${(b.skills||[]).join(", ")||"(choices only)"}.`;
    if(b.skillChoose) n += `\nAlso choose ${b.skillChoose.count} from ${b.skillChoose.from.join(", ")}.`;
    setNote(n);
  } else setNote("");
}

