// ---- Guided character creation wizard ----
let wizStep = 0, wizMethod = "manual";
const WIZ_LAST = 4;
function renderWizStep(){
  document.querySelectorAll(".wiz-step").forEach(s => s.hidden = (+s.dataset.step !== wizStep));
  $("wiz-back").style.visibility = wizStep === 0 ? "hidden" : "visible";
  $("wiz-next").textContent = wizStep === WIZ_LAST ? "Create" : "Next";
  $("wiz-dots").textContent = `Step ${wizStep + 1} of ${WIZ_LAST + 1}`;
}
function openWizard(){
  if(!PHB){ alert("Guided creation needs the PHB data — open the “Character Sheet (PHB).html” build."); return; }
  wizStep = 0; renderWizStep(); $("wizard").classList.add("open");
}
function closeWizard(){ $("wizard").classList.remove("open"); }
function raceHint(){
  const r = PHB && findBy(PHB.races, $("wiz-race").value);
  if(!r){ $("wiz-race-hint").textContent = ""; return; }
  const parts = [];
  (r.ability||[]).forEach(blk => Object.entries(blk).forEach(([k,v])=>{
    if(ABKEYS.includes(k)) parts.push(ABBR[k]+" +"+v);
    else if(k==="choose") parts.push(`+${v.amount||1} to ${v.count} of choice`);
  }));
  $("wiz-race-hint").textContent = (parts.length ? `Ability: ${parts.join(", ")}. ` : "") + (r.speed ? `Speed ${r.speed} ft.` : "");
}
function createCharacter(){
  const name=$("wiz-name").value.trim(), race=$("wiz-race").value, cls=$("wiz-class").value,
        sub=$("wiz-subclass").value, lvl=Math.min(20,Math.max(1,num($("wiz-level").value,1))), bg=$("wiz-bg").value;
