  document.querySelectorAll('#saves input[type="checkbox"], #skills input[type="checkbox"]').forEach(c=>c.checked=false);
  if(name) $("charname").value = name;
  if(race) applyRace(race);
  if(cls){
    applyClass(cls);
    const c = findBy(PHB.classes, cls);
    $("classlevel").value = cls + " " + lvl + (sub ? ` (${sub})` : "");
    if(c && c.hd) $("hitdice").value = lvl + "d" + c.hd;
  }
  if(bg) applyBackground(bg);
  genMode = wizMethod;
  if(wizMethod === "pointbuy") ABILITIES.forEach(([k])=>{ if(baseVals[k]==null||baseVals[k]<8||baseVals[k]>15) baseVals[k]=8; });
  renderAbilities(); updateModeUI();
  document.querySelectorAll("textarea").forEach(autoGrow);
  compute(); save(); closeWizard();
}

