           "image/heic":"heic","image/heif":"heif","image/avif":"avif","image/bmp":"bmp","image/tiff":"tif"})[t] || "img";
}
function renderPortrait(){
  const img=$("portrait-img"), empty=$("portrait-empty"), box=$("portrait");
  if(portraitData && portraitData.data){
    img.onerror = ()=>{ img.hidden=true; empty.hidden=false;          // e.g. HEIC can't preview in most browsers
      empty.textContent = (extFromType(portraitData.type)||"img").toUpperCase(); };
    img.src = portraitData.data; img.hidden=false; empty.hidden=true; box.classList.add("has-img");
  } else {
    img.hidden=true; img.removeAttribute("src"); empty.textContent="Portrait"; empty.hidden=false; box.classList.remove("has-img");
  }
}
function dataURLtoBlob(durl){
  const [head, b64] = durl.split(",");
  const mime = (head.match(/data:([^;]+)/) || [])[1] || "application/octet-stream";
  const bin = atob(b64), arr = new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) arr[i] = bin.charCodeAt(i);
  return new Blob([arr], {type:mime});
}
function downloadPortrait(){
  if(!portraitData) return;
  const url = URL.createObjectURL(dataURLtoBlob(portraitData.data));   // original bytes, full resolution
  const a = document.createElement("a");
  a.href = url; a.download = portraitData.name || ("portrait." + extFromType(portraitData.type));
  document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url), 1000);
}

