  Cleric:    {style:"prepared", ability:"wis", note:"Cleric: you know your whole class list; prepare a subset each day (Prep)."},
  Druid:     {style:"prepared", ability:"wis", note:"Druid: you know your whole class list; prepare a subset each day (Prep)."},
