  Bard:      {style:"known",    ability:"cha", note:"Bard: spells known are always ready — no preparation needed."},
  Sorcerer:  {style:"known",    ability:"cha", note:"Sorcerer: spells known are always ready — no preparation needed."},
  Ranger:    {style:"known",    ability:"wis", note:"Ranger: spells known are always ready — no preparation needed."},
