function defaultManualSpells(){ return Array.from({length:NSPELLROWS}, ()=>({lvl:"",name:"",prep:false})); }
function classSpellList(cls){
  const info = CASTERS[cls];
  return (info && info.fullList && PHB && PHB.classSpells && (PHB.classSpells[cls]||[]).length)
    ? PHB.classSpells[cls] : null;
