let preparedSpells = {};                     // {spellName: true} for pre-filled full-list classes
let spellEntries = {};                       // {lvl: [{name,prep}]} — write-your-own rows; lvl 0 = cantrips
let spellMaxLevel = 9;                        // highest spell-level section shown (sections shrink/grow on creation)
const CANTRIP_COUNT = 5, PER_LEVEL = 10;      // default blank entries per section
function mkSpellRows(n){ return Array.from({length:n}, ()=>({name:"",prep:false})); }
function defaultSpellEntries(){ const o = {0:mkSpellRows(CANTRIP_COUNT)}; for(let l=1;l<=9;l++) o[l]=mkSpellRows(PER_LEVEL); return o; }
function classSpellList(cls){
  const info = CASTERS[cls];
  return (info && info.fullList && PHB && PHB.classSpells && (PHB.classSpells[cls]||[]).length)
    ? PHB.classSpells[cls] : null;
}
// highest spell-slot level the character can use (used to shrink the sheet to fit the build)
function maxSpellLevel(cls, lvl){
  if(lvl == null) return 9;
  if(cls === "Warlock") return lvl>=9?5:lvl>=7?4:lvl>=5?3:lvl>=3?2:1;
  if(["Bard","Cleric","Druid","Sorcerer","Wizard"].includes(cls)) return Math.min(9, Math.ceil(lvl/2));   // full casters
  if(["Paladin","Ranger","Artificer"].includes(cls)) return lvl<2 ? 0 : Math.min(5, Math.floor(lvl/4)+1);  // half casters
  return 9;                                                                                                // Other / blank
}
function renderSpellTable(){
  const cls = $("spellclass").value, info = CASTERS[cls];
  $("spelltable").classList.toggle("hide-prep", !(info ? info.prepares : true));   // blank/Other shows Prep
  const full = classSpellList(cls);
  let fullByLvl = null;
  if(full){ fullByLvl = {}; full.forEach(sp => { (fullByLvl[sp.l] = fullByLvl[sp.l] || []).push(sp); }); }
  let body = "";
  for(let l=0; l<=spellMaxLevel; l++){
    body += `<tr class="sp-section"><td colspan="3">${l===0 ? "Cantrips" : "Level "+l}</td></tr>`;
    if(l>0 && fullByLvl){                      // full-list class → pre-fill this level's real spells (Prep checkbox each)
      (fullByLvl[l]||[]).forEach(sp => {
        body += `<tr><td class="col-lvl">${l}</td>`+
          `<td class="col-prep"><input type="checkbox" class="prep-spell" data-sp="${esc(sp.n)}" ${preparedSpells[sp.n] ? "checked" : ""}></td>`+
          `<td class="col-name">${esc(sp.n)}</td></tr>`;
      });
    } else {                                   // write-your-own rows (cantrips never show Lvl/Prep)
      (spellEntries[l]||[]).forEach((m,i) => {
        const lvlCell  = l===0 ? `<td class="col-lvl"></td>` : `<td class="col-lvl">${l}</td>`;
        const prepCell = l===0 ? `<td class="col-prep"></td>`
                                : `<td class="col-prep"><input type="checkbox" class="sp-prep" data-l="${l}" data-i="${i}" ${m.prep ? "checked" : ""}></td>`;
        body += `<tr>${lvlCell}${prepCell}<td class="col-name"><input class="sp-name" data-l="${l}" data-i="${i}" value="${esc(m.name||'')}"></td></tr>`;
      });
    }
  }
  $("spells").innerHTML = body;
}
function renderSpellStyle(setAbility){
  const cls = $("spellclass").value, info = CASTERS[cls];
  $("cast-note").textContent = info ? info.note : "Flexible layout — fill in as needed. Pick a class to tailor it.";
  if(info && setAbility && info.ability) $("spellability").value = info.ability;
  spellMaxLevel = (cls && CASTERS[cls]) ? maxSpellLevel(cls, charLevel()) : 9;   // shrink/grow sections to the build
  renderSpellTable();
}

