// spell-data lookup by name (components / time / range / duration / school / full text)
let _spellIndex = null;
function spellIndex(){
  if(!_spellIndex){ _spellIndex = {}; if(PHB && PHB.spells) PHB.spells.forEach(s => { _spellIndex[s.name.toLowerCase()] = s; }); }
  return _spellIndex;
}
function spellData(name){ return (name && spellIndex()[String(name).toLowerCase()]) || null; }
function propCells(d){                         // Comp / Cast Time / Range / Duration / School
  return `<td class="col-comp sp-comp">${d?esc(d.components||""):""}</td>`+
         `<td class="col-time sp-time">${d?esc(d.time||""):""}</td>`+
         `<td class="col-range sp-range">${d?esc(d.range||""):""}</td>`+
         `<td class="col-dur sp-dur">${d?esc(d.duration||""):""}</td>`+
         `<td class="col-school sp-school">${d?esc(d.school||""):""}</td>`;
}
function renderSpellTable(){
  const cls = $("spellclass").value, info = CASTERS[cls];
  $("spelltable").classList.toggle("hide-prep", !(info ? info.prepares : true));   // blank/Other shows Prep
  const full = classSpellList(cls);
  let fullByLvl = null;
  if(full){ fullByLvl = {}; full.forEach(sp => { (fullByLvl[sp.l] = fullByLvl[sp.l] || []).push(sp); }); }
  let body = "";
  for(let l=0; l<=spellMaxLevel; l++){
    body += `<tr class="sp-section"><td colspan="8">${l===0 ? "Cantrips" : "Level "+l}</td></tr>`;
    if(l>0 && fullByLvl){                      // full-list class → pre-fill this level's real spells (Prep checkbox each)
      (fullByLvl[l]||[]).forEach(sp => {
        const d = spellData(sp.n), titleAttr = (d && d.text) ? ` title="${esc(d.text)}"` : "";
        body += `<tr><td class="col-lvl">${l}</td>`+
          `<td class="col-prep"><input type="checkbox" class="prep-spell" data-sp="${esc(sp.n)}" ${preparedSpells[sp.n] ? "checked" : ""}></td>`+
          `<td class="col-name"${titleAttr}>${esc(sp.n)}</td>`+ propCells(d) +`</tr>`;
      });
    } else {                                   // write-your-own rows (cantrips never show Lvl/Prep)
