// ===== In-browser 5etools data processing (port of build-data.py) =====
const ET_SCHOOL = {A:"Abjuration",C:"Conjuration",D:"Divination",E:"Enchantment",V:"Evocation",I:"Illusion",N:"Necromancy",T:"Transmutation"};
const ET_DMG = {S:"slashing",P:"piercing",B:"bludgeoning",R:"radiant",F:"fire",C:"cold",L:"lightning",A:"acid",O:"force",Y:"psychic",T:"thunder",N:"necrotic"};
const ET_SIZE = {T:"Tiny",S:"Small",M:"Medium",L:"Large",H:"Huge",G:"Gargantuan"};
const ET_WPROP = {A:"ammunition",F:"finesse",H:"heavy",L:"light",LD:"loading",R:"reach",S:"special",T:"thrown","2H":"two-handed",V:"versatile"};
const ET_FULL = ["Cleric","Druid","Paladin","Artificer"];   // classes that prepare from their whole list
function etTags(s){
  if(typeof s !== "string") return s;
  let prev = null;
  while(prev !== s){ prev = s;
    s = s.replace(/\{@(\w+) ([^{}]*)\}/g, (m,tag,body) => {
      const p = body.split("|");
      if(["dice","damage","scaledamage","scaledice","d20","hit","dc"].includes(tag)) return p[0];
      if(p.length >= 3 && p[2].trim()) return p[2];
      return p[0];
    });
  }
  return s;
}
function etText(e){
  if(typeof e === "string") return etTags(e);
  if(Array.isArray(e)) return e.map(etText).filter(Boolean).join("\n");
  if(e && typeof e === "object"){
    if(e.type === "list") return (e.items||[]).map(i => "• "+etText(i)).join("\n");
    if(e.type === "table") return "";
    const inner = etText(e.entries||[]), name = e.name;
    return (name && inner) ? (name+". "+inner) : (name || inner || "");
  }
  return "";
}
function etProfList(lst){ return (lst||[]).map(x => typeof x==="string" ? etTags(x) : etTags((x&&x.proficiency)||"")).filter(Boolean); }
function etSkills(spo){
  let fixed = [], choose = null;
  (spo||[]).forEach(blk => { for(const k in blk){ const v = blk[k];
    if(k === "choose" && v && typeof v === "object") choose = {from:v.from||[], count:v.count||1};
    else if(v === true) fixed.push(k); } });
  return {fixed, choose};
