function mergeBook(into, add, bookName){
  into._meta = into._meta || {};
  into._meta.books = into._meta.books || (into._meta.book ? [into._meta.book] : []);
  ["races","backgrounds","classes","feats","spells","weapons","armor"].forEach(cat => {
    into[cat] = into[cat] || [];
    const idx = new Map(into[cat].map((x,i) => [x.name, i]));
    (add[cat]||[]).forEach(x => {                                  // overwrite existing (refreshes corrected data), else append
      if(idx.has(x.name)) into[cat][idx.get(x.name)] = x;
      else { idx.set(x.name, into[cat].length); into[cat].push(x); }
    });
  });
  { into.acItems = into.acItems || [];
    const idx = new Map(into.acItems.map((x,i) => [x.n, i]));
    (add.acItems||[]).forEach(x => { if(idx.has(x.n)) into.acItems[idx.get(x.n)] = x; else { idx.set(x.n, into.acItems.length); into.acItems.push(x); } });
    into.acItems.sort((a,b) => a.n.localeCompare(b.n)); }
  into.classSpells = into.classSpells || {};
  for(const cn in (add.classSpells||{})){
    const ex = into.classSpells[cn] = into.classSpells[cn] || [];
    const idx = new Map(ex.map((x,i) => [x.n, i]));
    add.classSpells[cn].forEach(x => { if(idx.has(x.n)) ex[idx.get(x.n)] = x; else { idx.set(x.n, ex.length); ex.push(x); } });
    ex.sort((a,b) => a.l-b.l || a.n.localeCompare(b.n));
  }
  if(bookName && !into._meta.books.includes(bookName)) into._meta.books.push(bookName);
}

