let wizStep = 0, wizMethod = "manual", wizEquip = "equipment";
const WIZ_LAST = 6;
function renderWizStep(){
  document.querySelectorAll(".wiz-step").forEach(s => s.hidden = (+s.dataset.step !== wizStep));
  $("wiz-back").style.visibility = wizStep === 0 ? "hidden" : "visible";
  $("wiz-next").textContent = wizStep === WIZ_LAST ? "Create" : "Next";
  $("wiz-dots").textContent = `Step ${wizStep + 1} of ${WIZ_LAST + 1}`;
  if(wizStep === 2) renderWizSkills();
  if(wizStep === 3) renderWizEquip();
}
function wizClass(){ return PHB && findBy(PHB.classes, $("wiz-class").value); }
function renderWizSkills(){
  const c = wizClass(), box = $("wiz-skills"), hint = $("wiz-skills-hint"), ch = c && c.skillChoose;
  if(!ch || !ch.from || !ch.from.length){ box.innerHTML = ""; hint.textContent = c ? "This class grants no skill choices." : "Pick a class first."; return; }
  box.innerHTML = ch.from.map(s => {
    const key = SKILL_KEY[s] || s, label = s.replace(/\b\w/g, m => m.toUpperCase());
    return `<label class="wiz-skill"><input type="checkbox" class="wiz-skill-cb" value="${esc(key)}"> <span>${esc(label)}</span></label>`;
  }).join("");
  hint.textContent = `Choose ${ch.count}.`;
  updateWizSkillLimit();
}
function updateWizSkillLimit(){
  const c = wizClass(), n = (c && c.skillChoose) ? c.skillChoose.count : 0;
  const cbs = [...document.querySelectorAll(".wiz-skill-cb")], checked = cbs.filter(x => x.checked).length;
  cbs.forEach(x => { const atMax = checked >= n && !x.checked; x.closest(".wiz-skill").classList.toggle("maxed", atMax); x.disabled = atMax; });
}
function goldAverage(f){
  if(!f) return null;
  const m = String(f).match(/(\d+)\s*d\s*(\d+)/i); if(!m) return null;
  let avg = (+m[1]) * ((+m[2]) + 1) / 2;
  const mul = String(f).match(/[×x*]\s*(\d+)/); if(mul) avg *= +mul[1];
  return Math.round(avg);
}
function renderWizEquip(){
  const c = wizClass(), hint = $("wiz-equip-hint"), eq = (c && c.equip) || {};
  document.querySelectorAll(".wiz-equip").forEach(b => b.classList.toggle("active", b.dataset.equip === wizEquip));
  if(wizEquip === "gold"){
    const g = goldAverage(eq.gold);
    hint.innerHTML = (g != null) ? `<strong>${g} gp</strong> (average of ${esc(eq.gold||"")}) will go in your Currency.` : "No starting-gold option listed for this class.";
  } else {
    const items = (eq.items || []);
    hint.innerHTML = items.length ? ("These go in Equipment Notes (resolve the “(a)/(b)” choices yourself):<br>• " + items.map(esc).join("<br>• ")) : "No starting equipment listed for this class.";
  }
}
function openWizard(){
  if(!PHB){ alert("Character creation needs sourcebook data. Open Settings → Source books and load a book from your 5etools server (or import a source-data.json)."); return; }
  wizStep = 0; wizEquip = "equipment"; renderWizStep(); $("wizard").classList.add("open");
}

