function parseEquipLine(line){
  const parts = String(line).split(/\([a-z]\)\s*/i);
  if(parts.length <= 1) return {fixed:true, text:String(line).trim()};         // no "(a)" marker → fixed grant
  const options = parts.slice(1).map(o => o.replace(/[,;]?\s*\bor\b\s*$/i,"").replace(/[,;]\s*$/,"").trim()).filter(Boolean);
  return {fixed:false, options};
}
function renderWizEquip(){
  const c = wizClass(), hint = $("wiz-equip-hint"), choices = $("wiz-equip-choices"), eq = (c && c.equip) || {};
  document.querySelectorAll(".wiz-equip").forEach(b => b.classList.toggle("active", b.dataset.equip === wizEquip));
  if(wizEquip === "gold"){
    choices.innerHTML = "";
    const g = goldAverage(eq.gold);
    hint.innerHTML = (g != null) ? `<strong>${g} gp</strong> (average of ${esc(eq.gold||"")}) will go in your Currency.` : "No starting-gold option listed for this class.";
  } else {
    const items = (eq.items || []);
    if(!items.length){ hint.textContent = "No starting equipment listed for this class."; choices.innerHTML = ""; return; }
    hint.textContent = "Choose an option for each line; your picks go into Inventory.";
    choices.innerHTML = items.map((line,i) => {
      const p = parseEquipLine(line);
      if(p.fixed) return `<div class="equip-line"><span class="equip-fixed">${esc(p.text)}</span></div>`;
      return `<div class="equip-line"><select class="equip-pick" data-i="${i}">` + p.options.map(o => optTag(o,o)).join("") + `</select></div>`;
    }).join("");
  }
}

