function parseEquipLine(line){
  const parts = String(line).split(/\([a-z]\)\s*/i);
  if(parts.length <= 1) return {fixed:true, text:String(line).trim()};         // no "(a)" marker → fixed grant
  const options = parts.slice(1).map(o => o.replace(/[,;]?\s*\bor\b\s*$/i,"").replace(/[,;]\s*$/,"").trim()).filter(Boolean);
  return {fixed:false, options};
}
const WEAPON_CAT_RE = /\b(two|a|an|any)?\s*(simple|martial)\s*(melee|ranged)?\s*weapons?\b/gi;
function detectWeaponSlots(optText){          // category weapon mentions → one slot each ("two ..." = 2)
  const slots = []; let m; WEAPON_CAT_RE.lastIndex = 0;
  while((m = WEAPON_CAT_RE.exec(optText))){ const n = /two/i.test(m[1]||"") ? 2 : 1; for(let k=0;k<n;k++) slots.push({cat:m[2].toLowerCase(), melee:(m[3]||"").toLowerCase()}); }
  return slots;
}
function weaponsFor(slot){
  return ((PHB && PHB.weapons) || []).filter(w => w.cat === slot.cat && (!slot.melee || (slot.melee === "melee" ? w.melee : !w.melee)));
}
function renderEquipSub(lineEl, optText){     // weapon-category dropdowns under a chosen option
  const sub = lineEl.querySelector(".equip-sub"); if(!sub) return;
  const slots = detectWeaponSlots(optText);
  sub.innerHTML = slots.map((s,si) => {
    const list = weaponsFor(s);
    return `<select class="equip-wpick" data-slot="${si}">` + list.map(w => optTag(w.name, w.name)).join("") + `</select>`;
  }).join("");
}
function matchPack(text){
  const packs = (PHB && PHB.packs) || {}, t = String(text).toLowerCase().replace(/^\s*(a|an)\s+/,"").trim();
  for(const name in packs){ if(name.toLowerCase() === t) return packs[name]; }
  return null;
}
function resolveEquipOption(optText, lineEl){  // chosen option text → list of concrete inventory entries
