const NOTE_DEFAULT = "Thresholds use your Strength score (lb). Encumbered / Heavily are the optional variant rule.";
if(strScore == null){
  ["enc5","enc10","carry","pushdrag","encstatus","effspeed"].forEach(id => $(id).textContent = "");
