  let status, penalty = 0, note = NOTE_DEFAULT;
  if(carried > carry){ status = "Over capacity"; penalty = baseSpeed||0; note = "Over capacity — you can't carry this much (more than Strength ×15)."; }
  else if(carried > enc10){ status = "Heavily encumbered"; penalty = 20; note = "Heavily encumbered: speed −20 ft, and disadvantage on STR/DEX/CON ability checks, attack rolls, and saving throws."; }
  else if(carried > enc5){ status = "Encumbered"; penalty = 10; note = "Encumbered: speed −10 ft."; }
  else status = "Unencumbered";
  $("encstatus").textContent = status;
  $("effspeed").textContent = (baseSpeed == null) ? "" : Math.max(0, baseSpeed - penalty) + " ft";
  $("encnote").textContent = note;
}

