  const h = e.target.closest(".invdrag"); if(!h){ e.preventDefault(); return; }
  invDrag = +h.closest("tr").dataset.r; e.dataTransfer.effectAllowed = "move"; try{ e.dataTransfer.setData("text/plain", String(invDrag)); }catch(_){}
});
invBody.addEventListener("dragover", e => {
  if(invDrag == null) return; e.preventDefault(); e.dataTransfer.dropEffect = "move";
  const tr = e.target.closest("tr"); invBody.querySelectorAll("tr.drop-target").forEach(r => r.classList.remove("drop-target")); if(tr) tr.classList.add("drop-target");
});
invBody.addEventListener("drop", e => {
  if(invDrag == null) return; e.preventDefault();
  const tr = e.target.closest("tr"); if(tr) moveInvRow(invDrag, +tr.dataset.r);
  invBody.querySelectorAll("tr.drop-target").forEach(r => r.classList.remove("drop-target")); invDrag = null;
});
invBody.addEventListener("dragend", () => { invBody.querySelectorAll("tr.drop-target").forEach(r => r.classList.remove("drop-target")); invDrag = null; });

