// classes whose spell list is a fixed, always-known set (seeded into the write-in rows on selection)
function seedFixedSpells(cls){
  const info = CASTERS[cls];
  if(!info || !info.fixed) return;
  if(!spellEntries || !Object.keys(spellEntries).length) spellEntries = defaultSpellEntries();
  Object.keys(info.fixed).forEach(key => {
    const l = +key;
    spellEntries[l] = spellEntries[l] || mkSpellRows(l===0 ? CANTRIP_COUNT : PER_LEVEL);
    info.fixed[key].forEach(name => {
      if(spellEntries[l].some(r => (r.name||"").trim().toLowerCase() === name.toLowerCase())) return;  // already present
      const slot = spellEntries[l].find(r => !(r.name||"").trim());
      if(slot) slot.name = name; else spellEntries[l].push({name, prep:false});
    });
  });
}

