// ---- Ability Score Improvements (flag + ASI/Feat picker) ----
// Levels at which a class grants an ASI (Fighter & Rogue get extras).
function classAsiLevels(cls){
  const c = (cls || "").toLowerCase();
  if(/fighter/.test(c)) return [4,6,8,12,14,16,19];
  if(/rogue/.test(c))   return [4,8,10,12,16,19];
  return [4,8,12,16,19];
}
// Count ASIs owed by parsing "Class N" pairs from the Class & Level field (handles multiclass).
function asiCount(){
  const str = $("classlevel").value || "";
  const re = /([A-Za-z'’][A-Za-z'’\- ]*?)\s+(\d+)/g;
  let m, total = 0, matched = false;
  while((m = re.exec(str))){ matched = true; const lv = parseInt(m[2],10); total += classAsiLevels(m[1]).filter(l => l <= lv).length; }
  if(!matched){ const lv = charLevel(); if(lv != null) total += classAsiLevels(str).filter(l => l <= lv).length; }
  return total;
}
function asiSlotComplete(s){
  if(!s || !s.type) return false;
  if(s.type === "asi")  return !!(s.ab1 || s.ab2);
  if(s.type === "feat") return !!s.feat;
  return false;
}
// Resize asiChoices to match the count the build is owed (keep existing choices).
function syncAsiSlots(){
  const n = asiCount();
  while(asiChoices.length < n) asiChoices.push({type:"", ab1:"", ab2:"", feat:""});
  if(asiChoices.length > n) asiChoices.length = n;
}
// ASI ability picks feed the "ASI" bonus column; recompute it from the chosen slots.
function applyAsiBonuses(){
  bonusVals.asi = zeroAb();
  asiChoices.forEach(s => {
    if(s.type !== "asi") return;
    if(s.ab1 && bonusVals.asi[s.ab1] != null) bonusVals.asi[s.ab1] += 1;
    if(s.ab2 && bonusVals.asi[s.ab2] != null) bonusVals.asi[s.ab2] += 1;
  });
  // chosen feats → append to the Features page once (never auto-removed)
  asiChoices.forEach(s => {
    if(s.type === "feat" && s.feat && !asiFeatsAdded[s.feat]){
      const f = (PHB && PHB.feats) ? PHB.feats.find(x => x.name === s.feat) : null;
      const line = "Feat: " + s.feat + (f && f.text ? ". " + f.text : "");
      const t = $("features");
      if(t && !(t.value||"").includes("Feat: " + s.feat)){ t.value = t.value.trim() ? t.value + "\n\n" + line : line; autoGrow(t); }
      asiFeatsAdded[s.feat] = true;
    }
  });
}
// The attention flag: shown until every owed ASI has a complete choice.
function updateAsiFlag(){
  syncAsiSlots();
