  if(pending > 0){
    flag.style.display = "";
    flag.innerHTML = "⚠ " + pending + " Ability Score Improvement" + (pending>1?"s":"") + " to assign"+
      "<span class=\"sub\">Click to choose an ASI (+2/+1+1) or a Feat for each.</span>";
  } else flag.style.display = "none";
}
function abilityOptions(sel){
