  const ed = (b.edition || "").toLowerCase();
  if(ed) return ed === "one" || ed.includes("2024");   // explicit edition tag wins, when present
  const code = (b.id || b.source || "").toUpperCase();
  if(RULESET_2024.has(code)) return true;
  return (b.published || "") >= "2024-09-01" && /core|supplement/.test(b.group || "");   // future 2024 rulebooks
}
async function populateBookSelect(){
  const sel = $("book-select"); if(!sel) return;
  const base = ($("server-url").value || "").trim() || "http://localhost:5050";
  sel.innerHTML = '<option value="">Loading book list…</option>'; sel.disabled = true;
  try{
    const bj = await fetch(base.replace(/\/+$/,"")+"/data/books.json").then(r => { if(!r.ok) throw 0; return r.json(); });
    const books = (bj.book||[]).slice().sort((a,b) => (a.name||"").localeCompare(b.name||""));
    const opt = b => `<option value="${esc(b.id||b.source)}">${esc(b.name||b.id)}</option>`;
    const grp = (label, list) => list.length ? `<optgroup label="${label}">` + list.map(opt).join("") + `</optgroup>` : "";
    sel.innerHTML = '<option value="">Pick a book…</option>'
      + grp("2014 ruleset", books.filter(b => !isBook2024(b)))
      + grp("2024 ruleset", books.filter(isBook2024));
    sel.disabled = false;
  }catch(e){ sel.innerHTML = '<option value="">Start your 5etools server, then reopen Settings</option>'; sel.disabled = true; }
}

