function etClasses(data, SRC){
  // All subclasses from THIS book, grouped by base-class name — even when the base class lives in another
  // book (e.g. TCE's Order of Scribes belongs to the PHB Wizard). mergeBook attaches these to the class.
  const subMap = {};
  (data.subclass||[]).forEach(s => {
    if(s.source !== SRC || !s.className) return;
    const short = s.shortName||s.name;
    const arr = subMap[s.className] = subMap[s.className] || [];
    if(!arr.some(x => x.short === short)) arr.push({name:s.name, short});
  });
  const classes = (data.class||[]).filter(c => c.source === SRC).map(c => {
    const sp = c.startingProficiencies || {};
    const {fixed:skFixed, choose:skChoose} = etSkills(sp.skills);
    const se = c.startingEquipment || {};
    const equip = {items:(se.default||[]).filter(x => typeof x === "string").map(etTags), gold:etTags(se.goldAlternative||"")};
    const features = (data.classFeature||[])
      .filter(f => f.source === SRC && f.className === c.name && (f.classSource||SRC) === SRC && f.name)
      .map(f => ({name:f.name||"", level:f.level||1, text:etText(f.entries||[])}))
      .sort((a,b) => a.level-b.level || a.name.localeCompare(b.name));
    let subLvl = null;
    for(const f of (c.classFeatures||[])){
      if(f && typeof f === "object" && f.gainSubclassFeature && f.classFeature){
        const n = parseInt(String(f.classFeature).split("|")[3], 10); subLvl = isNaN(n) ? null : n; break;
      }
    }
    return {name:c.name, hd:(c.hd||{}).faces, saves:c.proficiency||[], skillChoose:skChoose, skillsFixed:skFixed,
      armor:etProfList(sp.armor), weapons:etProfList(sp.weapons), casterAbility:c.spellcastingAbility, casterProgression:c.casterProgression,
      cantrips:c.cantripProgression||null, equip, features, subclassTitle:c.subclassTitle||"", subclassLevel:subLvl, subclasses:(subMap[c.name]||[])};
  });
  return {classes, subclasses: subMap};

