// ASI ability picks + half-feat ability increases feed the "ASI" bonus column; recompute from the chosen slots.
function applyAsiBonuses(){
  bonusVals.asi = zeroAb();
  const featOf = name => (DATA && DATA.feats) ? DATA.feats.find(x => x.name === name) : null;
  asiChoices.forEach(s => {
    if(s.type === "asi"){
      if(s.ab1 && bonusVals.asi[s.ab1] != null) bonusVals.asi[s.ab1] += 1;
      if(s.ab2 && bonusVals.asi[s.ab2] != null) bonusVals.asi[s.ab2] += 1;
    } else if(s.type === "feat" && s.feat){            // half-feat ability increase
      const f = featOf(s.feat);
      if(f && f.ability){
        for(const k in (f.ability.fixed||{})) if(bonusVals.asi[k] != null) bonusVals.asi[k] += f.ability.fixed[k];
        if(f.ability.choose && s.featAbil && bonusVals.asi[s.featAbil] != null) bonusVals.asi[s.featAbil] += (f.ability.choose.amount || 1);
      }
    }
  });
  // chosen feats → apply proficiencies/saves + append to Features page once (never auto-removed)
  asiChoices.forEach(s => {
    if(s.type === "feat" && s.feat && !asiFeatsAdded[s.feat]){
      const f = featOf(s.feat);
      const line = "Feat: " + s.feat + (f && f.text ? ". " + f.text : "");
      const t = $("features");
      if(t && !(t.value||"").includes("Feat: " + s.feat)){ t.value = t.value.trim() ? t.value + "\n\n" + line : line; autoGrow(t); }
      if(FEAT_SENSES[s.feat]) addSense(FEAT_SENSES[s.feat]);   // sense-affecting feats also land in the Senses box
      if(f){
        applyProficiencies(f.prof, s.feat);              // feat skill/tool/language/weapon/armor proficiencies
        if(f.saves){                                     // Resilient etc. → save-proficiency checkbox
          (f.saves.fixed||[]).forEach(k => { const box = $("savep-"+k); if(box) box.checked = true; });
          if(f.saves.choose && s.featAbil){ const box = $("savep-"+s.featAbil); if(box) box.checked = true; }
        }
      }
      asiFeatsAdded[s.feat] = true;
    }
  });
}

