// ---- "Active" weapons → Attacks table (toggled per inventory row; bonus & damage auto-computed) ----
function weaponByName(name){
  const n = String(name||"").trim().toLowerCase();
  return ((DATA && DATA.weapons) || []).find(w => (w.name||"").toLowerCase() === n) || null;
}
function weaponAtkAbility(w){               // attack/damage ability: melee→Str, ranged→Dex, finesse→better of the two
  const finesse = (w.props||[]).some(p => /finesse/i.test(p));
  if(finesse) return (modOf("dex") >= modOf("str")) ? "dex" : "str";
  return w.melee ? "str" : "dex";
}
function weaponAtkRow(w){                   // {bonus, dmg} from current scores, assuming proficiency
  const m = modOf(weaponAtkAbility(w)), lvl = charLevel(), pb = (lvl == null) ? 0 : 2 + Math.floor((lvl-1)/4);
  const md = s => s > 0 ? "+"+s : (s < 0 ? ""+s : "");
  let dmg = (w.dmg||"") + (m ? md(m) : "") + (w.dmgType ? " " + w.dmgType : "");
  if(w.versatile) dmg += ` (${w.versatile}${m ? md(m) : ""} versatile)`;
  if(w.range)     dmg += `, range ${w.range}`;
  return {bonus: sgn(m + pb), dmg: dmg.trim()};
}
function setWeaponActive(name, on){        // add/remove this weapon's derived Attacks row (linked via dataset.weapon)
  const lc = String(name||"").trim().toLowerCase();
  let idx = -1;
  for(let i=0;i<NATTACKS;i++){ const el = $("atkname-"+i); if(el && el.dataset.weapon && el.dataset.weapon.toLowerCase() === lc){ idx = i; break; } }
  if(on){
    if(idx < 0) for(let i=0;i<NATTACKS;i++){ const el = $("atkname-"+i); if(el && !el.value){ idx = i; break; } }
    if(idx < 0){ flashStatus("Attacks table is full — clear a row first"); return; }
    const w = weaponByName(name); if(!w) return;
    $("atkname-"+idx).value = w.name; $("atkname-"+idx).dataset.weapon = w.name;
  } else if(idx >= 0){
    $("atkname-"+idx).value = ""; delete $("atkname-"+idx).dataset.weapon;
    $("atkbonus-"+idx).value = ""; $("atkdmg-"+idx).value = "";
  }
}
function refreshAtkRows(){                  // recompute every derived (weapon-linked) Attacks row; lock its inputs
  for(let i=0;i<NATTACKS;i++){ const nm = $("atkname-"+i); if(!nm) continue;
    const linked = !!nm.dataset.weapon, w = linked ? weaponByName(nm.dataset.weapon) : null;
    [nm, $("atkbonus-"+i), $("atkdmg-"+i)].forEach(el => { if(el) el.readOnly = linked; });
    if(w){ const r = weaponAtkRow(w); $("atkbonus-"+i).value = r.bonus; $("atkdmg-"+i).value = r.dmg; }
  }
}
function refreshAtkToggles(){               // show the "Atk" checkbox only on weapon rows; reflect active state
  const active = new Set();
  for(let i=0;i<NATTACKS;i++){ const el = $("atkname-"+i); if(el && el.dataset.weapon) active.add(el.dataset.weapon.toLowerCase()); }
  for(let i=0;i<NINV;i++){ const cb = $("invatk-"+i), nm = $("invname-"+i); if(!cb || !nm) continue;
    const isW = !!weaponByName(nm.value);
    cb.style.display = isW ? "" : "none";
    cb.checked = isW && active.has((nm.value||"").trim().toLowerCase());
  }
}

