function isMonkWeapon(w){                   // shortsword, or any simple melee weapon without two-handed/heavy
  if(!w) return false;
  if(/shortsword/i.test(w.name||"")) return true;
  const heavy2h = (w.props||[]).some(p => /two-handed|heavy/i.test(p));
  return w.cat === "simple" && w.melee && !heavy2h;
