// Attack/damage ability: base finesse/melee/ranged, plus class-feature substitutions, then use the best modifier.
// Handled (2014): Monk Martial Arts (Dex on monk weapons), Hexblade Hex Warrior (Cha on melee/pact weapons),
// Battle Smith Artificer (Int on magic weapons). Spell-based Shillelagh (Wis on club/quarterstaff) stays manual.
function weaponAtkAbility(w){
  const cls = ($("classlevel").value || "").toLowerCase();
  const finesse = (w.props||[]).some(p => /finesse/i.test(p));
  const allowed = new Set();
  allowed.add(w.melee ? "str" : "dex");                              // base
  if(finesse){ allowed.add("str"); allowed.add("dex"); }            // finesse → either
  if(/\bmonk\b/.test(cls) && isMonkWeapon(w)) allowed.add("dex");   // Martial Arts
  if(/hexblade/.test(cls) && w.melee) allowed.add("cha");           // Hex Warrior (pact/bonded weapon)
  if(/battle\s*smith/.test(cls)) allowed.add("int");               // Battle Smith (magic weapons)
  return [...allowed].sort((a,b) => modOf(b) - modOf(a))[0] || "str";   // best available modifier
}

