// Auto-apply the deterministic parts of a template to a creature (called on fresh monster base).
function applyCompanionTemplate(c){
  const t = c.template, lvl = charLevel(), pb = (lvl == null) ? 0 : 2 + Math.floor((lvl-1)/4);
  if(t === "companion" && c.monster){                 // Beast Master: + prof to AC, HP = max(normal, 4×level)
    const acm = String(c.ac||"").match(/-?\d+/);
    if(acm) c.ac = String(parseInt(acm[0],10) + pb) + String(c.ac).slice(acm.index + acm[0].length);
    const hpn = parseInt(c.hp,10);
    if(!isNaN(hpn)){ const nh = Math.max(hpn, 4*(lvl||0)); c.hp = String(nh); c.curhp = String(nh); }
    if(lvl != null) c.pb = sgn(pb);
  } else if(t === "wildshape"){                        // keep your mental stats + proficiency bonus
    ["int","wis","cha"].forEach(a => { const v = finalScore(a); if(v != null) c[a] = String(v); });
    if(lvl != null) c.pb = sgn(pb);
  }
}

