// Single-class spell-slot tables (slots per spell level by character level). Rules math, not content.
const SLOTS_FULL = {1:[2],2:[3],3:[4,2],4:[4,3],5:[4,3,2],6:[4,3,3],7:[4,3,3,1],8:[4,3,3,2],9:[4,3,3,3,1],10:[4,3,3,3,2],11:[4,3,3,3,2,1],12:[4,3,3,3,2,1],13:[4,3,3,3,2,1,1],14:[4,3,3,3,2,1,1],15:[4,3,3,3,2,1,1,1],16:[4,3,3,3,2,1,1,1],17:[4,3,3,3,2,1,1,1,1],18:[4,3,3,3,3,1,1,1,1],19:[4,3,3,3,3,2,1,1,1],20:[4,3,3,3,3,2,2,1,1]};
const SLOTS_HALF = {2:[2],3:[3],4:[3],5:[4,2],6:[4,2],7:[4,3],8:[4,3],9:[4,3,2],10:[4,3,2],11:[4,3,3],12:[4,3,3],13:[4,3,3,1],14:[4,3,3,1],15:[4,3,3,2],16:[4,3,3,2],17:[4,3,3,3,1],18:[4,3,3,3,1],19:[4,3,3,3,2],20:[4,3,3,3,2]};
const SLOTS_ARTIFICER = Object.assign({1:[2]}, SLOTS_HALF);   // half-caster table but rounds up (slots from level 1)
const SLOTS_THIRD = {3:[2],4:[3],5:[3],6:[3],7:[4,2],8:[4,2],9:[4,2],10:[4,3],11:[4,3],12:[4,3],13:[4,3,2],14:[4,3,2],15:[4,3,2],16:[4,3,3],17:[4,3,3],18:[4,3,3],19:[4,3,3,1],20:[4,3,3,1]};
function autoSlots(cls, lvl){                  // -> {spellLevel: count} for a known single-class caster, {} if no slots yet, null if manual
  if(lvl == null) return null;
  const L = Math.min(20, Math.max(1, lvl));
  if(cls === "Warlock"){ const cnt = L>=17?4:L>=11?3:L>=2?2:1, lev = L>=9?5:Math.ceil(L/2); return {[lev]:cnt}; }
  let tbl = null;
  if(["Bard","Cleric","Druid","Sorcerer","Wizard"].includes(cls)) tbl = SLOTS_FULL;
  else if(["Paladin","Ranger"].includes(cls)) tbl = SLOTS_HALF;
  else if(cls === "Artificer") tbl = SLOTS_ARTIFICER;
  else if(THIRD_CASTERS.includes(cls)) tbl = SLOTS_THIRD;
  if(!tbl) return null;
  const row = tbl[L]; if(!row) return {};      // caster, but no slots at this level yet
  const map = {}; row.forEach((c,i) => { if(c) map[i+1] = c; }); return map;
}
function refreshSpellSlots(){                  // auto-fill (and lock) the Total boxes for a known single-class caster
  const cls = $("spellclass").value;
  const multi = (((($("classlevel").value||"").match(/[A-Za-z'’][A-Za-z'’\- ]*?\s+\d+/g))||[]).length) > 1;
  const map = multi ? null : autoSlots(cls, charLevel());   // multiclass slots are manual (don't stack cleanly)
  for(let l=1;l<=9;l++){
    const tot = $("slot"+l); if(!tot) continue;
    if(map){ const c = map[l]; tot.value = (c != null) ? String(c) : ""; tot.readOnly = true; }
    else if(tot.readOnly){ tot.value = ""; tot.readOnly = false; }   // reverting to manual: clear the stale auto value, unlock
  }
}
function applySlotFilter(){                    // show only slot levels the build can use (matches the spell list)
  const info = CASTERS[$("spellclass").value];
  const card = $("slots-card"); if(card) card.style.display = (info && info.noSlots) ? "none" : "";   // ki casters (Shadow Monk) use no slots
  for(let l=1;l<=9;l++){ const c = $("slotcell"+l); if(c) c.style.display = (l <= spellMaxLevel) ? "" : "none"; }
  refreshSpellSlots();
}

