function etItems(raw, itemsData, SRC){
  const weapons = [], armor = [];
  (raw.baseitem||[]).forEach(it => {
    if(it.source !== SRC) return;
    if(it.weapon) weapons.push({name:it.name, cat:it.weaponCategory==="martial"?"martial":"simple", melee:it.type==="M", dmg:it.dmg1||"", dmgType:ET_DMG[it.dmgType]||it.dmgType||"", versatile:it.dmg2||"", props:(it.property||[]).map(p=>ET_WPROP[p]||p), range:it.range||""});
    else if(it.armor || ["LA","MA","HA","S"].includes(it.type||"")) armor.push({name:it.name, ac:it.ac, type:it.type||"", stealth:!!it.stealth, strength:it.strength});
  });
  // named magic armors (Elven Chain, Dwarven Plate, ...) live in items.json, not baseitem
  (((itemsData||{}).item)||[]).forEach(it => {
    if(it.source !== SRC) return;
    const ty = (it.type||"").split("|")[0];
    if(["LA","MA","HA"].includes(ty) && it.ac != null) armor.push({name:it.name, ac:it.ac, type:ty, stealth:!!it.stealth, strength:it.strength});
  });
  return {weapons, armor};
}

