  const sel = $("book-select"); if(!sel) return;
  const base = ($("server-url").value || "").trim() || "http://localhost:5050";
  sel.innerHTML = '<option value="">Loading book list…</option>'; sel.disabled = true;
  try{
    const bj = await fetch(base.replace(/\/+$/,"")+"/data/books.json").then(r => { if(!r.ok) throw 0; return r.json(); });
    // This is a 2014-ruleset sheet — 2024 books are filtered out (a 2024-compliant sheet is on the roadmap).
    // Already-loaded books stay in the list (marked) so you can re-load one to refresh its data.
    const loaded = new Set(loadedBooks().map(n => String(n).toLowerCase()));
    const books = (bj.book||[])
      .filter(b => !isBook2024(b))
      .sort((a,b) => (a.name||"").localeCompare(b.name||""));
    sel.innerHTML = '<option value="">Pick a book…</option>'
      + books.map(b => { const nm = b.name||b.id, isLd = loaded.has(String(nm).toLowerCase());
          return `<option value="${esc(b.id||b.source)}" data-name="${esc(nm)}">${esc(nm)}${isLd ? " (loaded — reload to refresh)" : ""}</option>`; }).join("");
    sel.disabled = !books.length;
  }catch(e){ sel.innerHTML = '<option value="">Start your 5etools server, then reopen Settings</option>'; sel.disabled = true; }
}
async function loadBookFromServer(){
  const sel = $("book-select"), srcCode = sel && sel.value;
  if(!srcCode){ flashStatus("Pick a book first"); return; }
  const opt = sel.options[sel.selectedIndex];
  const bookName = (opt && opt.dataset && opt.dataset.name) || (opt ? opt.textContent : srcCode);   // clean name (no "(loaded…)" suffix)
  const wasLoaded = new Set(loadedBooks().map(n => String(n).toLowerCase())).has(String(bookName).toLowerCase());
  const base = ($("server-url").value || "").trim() || "http://localhost:5050";
  const btn = $("btn-loadbook"); if(btn){ btn.disabled = true; btn.textContent = wasLoaded ? "Reloading…" : "Loading…"; }
  try{
    const data = await fetch5etoolsBook(base, srcCode);
    if(!DATA) DATA = {_meta:{books:[]}};
    mergeBook(DATA, data, bookName);
    _spellIndex = null;
    bakeSourceData();   // keep the in-document data block in sync so saves carry the books
    try{ localStorage.setItem(SOURCES_KEY, JSON.stringify(DATA)); }
    catch(e){ flashStatus(bookName+" loaded (too large to save — stays this session)"); }
    populateWizard(); populateArmor(); renderSpellStyle(false); updateSourcebookStatus(); populateMonsterList(); compute();
