async function populateBookSelect(){
  const sel = $("book-select"); if(!sel) return;
  const rsel = $("reload-select"), rrow = $("reload-row");
  const base = ($("server-url").value || "").trim() || "http://localhost:5050";
  sel.innerHTML = '<option value="">Loading book list…</option>'; sel.disabled = true;
  const opt = b => `<option value="${esc(b.id||b.source)}" data-name="${esc(b.name||b.id)}">${esc(b.name||b.id)}</option>`;
  try{
    const bj = await fetch(base.replace(/\/+$/,"")+"/data/books.json").then(r => { if(!r.ok) throw 0; return r.json(); });
    // 2014-ruleset sheet — 2024 books are filtered out. Not-yet-loaded books go in the main picker;
    // already-loaded books go in a separate "reload" picker so you can refresh one's data.
    const loaded = new Set(loadedBooks().map(n => String(n).toLowerCase()));
    const books = (bj.book||[]).filter(b => !isBook2024(b)).sort((a,b) => (a.name||"").localeCompare(b.name||""));
    const isLd = b => loaded.has(String(b.name||b.id||"").toLowerCase());
    const fresh = books.filter(b => !isLd(b)), reload = books.filter(isLd);
    sel.innerHTML = (fresh.length ? '<option value="">Pick a book…</option>' : '<option value="">All available books already loaded</option>') + fresh.map(opt).join("");
    sel.disabled = !fresh.length;
    if(rsel){ rsel.innerHTML = '<option value="">Pick a loaded book…</option>' + reload.map(opt).join(""); rsel.disabled = !reload.length; }
    if(rrow) rrow.style.display = reload.length ? "" : "none";
  }catch(e){ sel.innerHTML = '<option value="">Start your 5etools server, then reopen Settings</option>'; sel.disabled = true; if(rrow) rrow.style.display = "none"; }
}
async function doLoadBook(srcCode, bookName, reloading, btn){   // shared by the load + reload pickers
  const base = ($("server-url").value || "").trim() || "http://localhost:5050";
  const orig = btn ? btn.textContent : "";
  if(btn){ btn.disabled = true; btn.textContent = reloading ? "Reloading…" : "Loading…"; }
  try{
    const data = await fetch5etoolsBook(base, srcCode);
    if(!DATA) DATA = {_meta:{books:[]}};
    mergeBook(DATA, data, bookName);
    _spellIndex = null;
    bakeSourceData();   // keep the in-document data block in sync so saves carry the books
    try{ localStorage.setItem(SOURCES_KEY, JSON.stringify(DATA)); }
    catch(e){ flashStatus(bookName+" loaded (too large to save — stays this session)"); }
    populateWizard(); populateArmor(); renderSpellStyle(false); updateSourcebookStatus(); populateMonsterList(); compute();
    populateBookSelect();   // move the just-loaded book over to the reload picker
    flashStatus(bookName + (reloading ? " reloaded (data refreshed)" : " loaded — use “Save data file” to bake it into your sheet"));
  }catch(e){ flashStatus((reloading?"Reload":"Load")+" failed — is your 5etools server running at "+base+"?"); }
  finally{ if(btn){ btn.disabled = false; btn.textContent = orig || "Load"; } }
}
function bookFromSelect(sel){ const o = sel && sel.options[sel.selectedIndex]; return o ? {code:sel.value, name:(o.dataset && o.dataset.name) || o.textContent} : null; }
function loadBookFromServer(){
  const b = bookFromSelect($("book-select"));
  if(!b || !b.code){ flashStatus("Pick a book first"); return; }
  doLoadBook(b.code, b.name, false, $("btn-loadbook"));
}
function reloadBookFromServer(){
  const b = bookFromSelect($("reload-select"));
  if(!b || !b.code){ flashStatus("Pick a loaded book to reload"); return; }
  doLoadBook(b.code, b.name, true, $("btn-reloadbook"));
}

