function populateItemList(){ const dl = $("item-options"); if(!dl) return; const names = (DATA && DATA.itemNames) || []; dl.innerHTML = names.map(n => `<option value="${esc(n)}"></option>`).join(""); }
function setupItemSearch(){   // substring-searchable picker that adds an item to the next empty row
  const inp = $("item-search"), res = $("item-results"); if(!inp || !res) return;
  let matches = [], sel = -1;
  function paint(){ [...res.querySelectorAll(".opt")].forEach((o,i) => o.classList.toggle("sel", i === sel)); const s = res.querySelector(".opt.sel"); if(s) s.scrollIntoView({block:"nearest"}); }
  function render(){
    const q = inp.value.trim().toLowerCase();
    if(!q){ res.hidden = true; res.innerHTML = ""; matches = []; sel = -1; return; }
    const names = (DATA && DATA.itemNames) || [];
    matches = names.filter(n => n.toLowerCase().includes(q)).slice(0, 50);
    sel = matches.length ? 0 : -1;
    res.innerHTML = matches.length
      ? matches.map((n,i) => { const w = itemWeight(n); return `<div class="opt${i===0?' sel':''}" data-i="${i}">${esc(n)}${w!=null?`<span class="w">${w} lb</span>`:''}</div>`; }).join("")
      : '<div class="opt none">No matching items (load the right sourcebook?)</div>';
    res.hidden = false;
  }
  function add(name){ if(!name) return; addInvItem(name, 1); inp.value = ""; res.hidden = true; res.innerHTML = ""; matches = []; sel = -1; save(); compute(); inp.focus(); }
  inp.addEventListener("input", render);
  inp.addEventListener("focus", () => { if(inp.value.trim()) render(); });
  inp.addEventListener("keydown", e => {
    if(res.hidden || !matches.length) return;
    if(e.key === "ArrowDown"){ e.preventDefault(); sel = Math.min(sel+1, matches.length-1); paint(); }
    else if(e.key === "ArrowUp"){ e.preventDefault(); sel = Math.max(sel-1, 0); paint(); }
    else if(e.key === "Enter"){ e.preventDefault(); add(matches[sel]); }
    else if(e.key === "Escape"){ res.hidden = true; }
  });
  res.addEventListener("mousedown", e => { const o = e.target.closest(".opt"); if(o && o.dataset.i != null){ e.preventDefault(); add(matches[+o.dataset.i]); } });   // mousedown beats input blur
  document.addEventListener("click", e => { if(!e.target.closest(".item-search-wrap")) res.hidden = true; });
}

