function etLangChoose(arr){   // number of free language choices a race grants (any / anyStandard / anyExotic / choose)
  let n = 0;
  (arr||[]).forEach(blk => { if(!blk || typeof blk !== "object") return;
    for(const k in blk){ const v = blk[k];
      if((k === "any" || k === "anyStandard" || k === "anyExotic") && typeof v === "number") n += v;
      else if(k === "choose" && v && typeof v === "object") n += (v.count || 1); } });
  return n;
}
function etRaces(raw, SRC){
  const out = [], bases = {}, baseIdx = {};
  (raw.race||[]).forEach(r => {
    if(r.source !== SRC) return;
    const ab = (r.ability||[]).slice(), fg = etFeatGrants(r), pf = etProfBlock(r), rs = etDamageResist(r);
