    baseIdx[r.name] = out.length;
    out.push({name:r.name, ability:ab, size:(r.size||[]).map(s=>ET_SIZE[s]||s).join("/")||"Medium", speed:etSpeed(r), traits:etTraits(r.entries||[]), featGrants:fg, prof:pf, resist:rs, darkvision:dv, langChoose:lc});
  });
  (raw.subrace||[]).forEach(s => {
    if(s.source !== SRC) return;
    const parent = s.raceName, sdv = s.darkvision||0, slc = etLangChoose(s.languageProficiencies);
    if(!s.name){ const i = baseIdx[parent]; if(i != null){ out[i].ability = (out[i].ability||[]).concat(s.ability||[]); out[i].traits = (out[i].traits||[]).concat(etTraits(s.entries||[])); out[i].featGrants = (out[i].featGrants||0) + etFeatGrants(s); out[i].prof = etMergeProf(out[i].prof, etProfBlock(s)); out[i].resist = (out[i].resist||[]).concat(etDamageResist(s)); out[i].darkvision = Math.max(out[i].darkvision||0, sdv); out[i].langChoose = (out[i].langChoose||0) + slc; } return; }
    const base = bases[parent] || {};
    out.push({name:parent+" ("+s.name+")", ability:(base.ability||[]).concat(s.ability||[]), size:"", speed:(s.speed != null ? etSpeed(s) : (base.speed||30)), subraceOf:parent, traits:(base.traits||[]).concat(etTraits(s.entries||[])), featGrants:(base.featGrants||0) + etFeatGrants(s), prof:etMergeProf(base.prof, etProfBlock(s)), resist:(base.resist||[]).concat(etDamageResist(s)), darkvision:Math.max(base.darkvision||0, sdv), langChoose:(base.langChoose||0)+slc});
  });
  out.forEach(o => { if(/custom lineage/i.test(o.name)) o.variableSkillDarkvision = true; });   // TCE Custom Lineage: skill proficiency OR darkvision (5etools lists both; the rule is a choice)
