function addLanguages(langs){
  langs = (Array.isArray(langs) ? langs : [langs]).map(s => String(s).trim()).filter(Boolean);
  if(!langs.length) return;
  const p = $("proficiencies"); if(!p) return;
  const lines = p.value ? p.value.split("\n") : [];
  const idx = lines.findIndex(l => /^\s*Languages:/i.test(l));
  const cur = idx >= 0 ? lines[idx].replace(/^\s*Languages:\s*/i, "").split(",").map(s => s.trim()).filter(Boolean) : [];
  langs.forEach(l => { if(!cur.some(e => e.toLowerCase() === l.toLowerCase())) cur.push(l); });
  const line = "Languages: " + cur.join(", ");
  if(idx >= 0) lines[idx] = line; else lines.push(line);
  p.value = lines.join("\n"); autoGrow(p);
}
