    const name = (nm.value||"").trim(), cont = rowCont(i), isCont = name && have.has(name);
    caret.className = "cont-caret"; caret.textContent = ""; tr.style.display = ""; tr.classList.toggle("in-container", !!cont);
    if(drag){ drag.textContent = "⠿"; delete drag.dataset.cont; drag.classList.remove("cont-toggle"); drag.title = "Drag to reorder"; }
