// Detect a limited daily/rest use from a feature/feat/item description → {name, max, rec} or null.
function limitedFromText(name, text){
  if(!name) return null;
  const t = " " + String(text||"").toLowerCase().replace(/\s+/g, " ") + " ";
  let rec = null;
  if(/short or long rest|short rest/.test(t)) rec = "SR";
  else if(/long rest/.test(t)) rec = "LR";
  else if(/\bat dawn\b|\beach dawn\b|\bnext dawn\b/.test(t)) rec = "Dawn";
  else if(/\bper day\b|\/day\b|\beach day\b/.test(t)) rec = "1/Day";
  if(!rec) return null;
  const countRe = /\b(\d+)\s+(?:charges|uses|luck points|ki points|sorcery points)\b/;
  const usage =
    countRe.test(t) ||
    /\b(?:expend|spend)s?\b[^.]{0,40}\b(?:charge|use|luck point|ki point|sorcery point)\b/.test(t) ||
    /\bregains?\b[^.]{0,60}\b(?:expended|all)\b[^.]{0,30}\b(?:charges|uses|luck points|ki points|sorcery points)\b/.test(t) ||
    /\b(?:once|twice|three times|\d+ times)\b[^.]{0,60}\b(?:rest|dawn|day)\b/.test(t) ||
    /\bcan'?t use (?:it|this)\b[^.]{0,50}\bagain\b[^.]{0,40}\b(?:rest|dawn|day)\b/.test(t) ||
    /\bnumber of times equal to\b/.test(t);
  if(!usage) return null;
  const m = countRe.exec(t);
  return {name, max: m ? m[1] : "", rec};
}
function addLimitedRow(name, max, rec, desc){   // add a Limited Features row if not already listed (never clobbers existing rows)
  if(!name) return;
  for(let i=0;i<NLIMITED;i++){ if(($("lfname-"+i).value||"").trim().toLowerCase() === name.toLowerCase()) return; }
  let idx = -1; for(let i=0;i<NLIMITED;i++){ if(!($("lfname-"+i).value||"").trim()){ idx = i; break; } }
  if(idx < 0) return;   // card full
  $("lfname-"+idx).value = name; $("lfmax-"+idx).value = (max!=null && max!=="") ? String(max) : ""; $("lfrec-"+idx).value = rec || "";
  if(desc) $("lfname-"+idx).title = desc;
}
function featureBlocks(){   // parse the Features box into {name, text} blocks
  const v = ($("features").value||""); if(!v.trim()) return [];
  return v.split(/\n\s*\n+/).map(b => {
    const s = b.trim().replace(/^Feat:\s*/i, "");
    const cuts = [s.indexOf(" ("), s.indexOf(". ")].filter(x => x >= 0); const cut = cuts.length ? Math.min(...cuts) : s.length;
    return {name: s.slice(0, cut).trim(), text: b};
  }).filter(x => x.name);
}
function refreshLimitedFeatures(){   // auto-add limited-use class/subclass features, feats, and equipped items
  featureBlocks().forEach(b => {
    if(LIMITED_FEAT_NAMES.has(b.name.toLowerCase())) return;
    const r = limitedFromText(b.name, b.text); if(r) addLimitedRow(r.name, r.max, r.rec, b.text.slice(0,300));
  });
  const txt = (DATA && DATA.itemText) || {};
  for(let i=0;i<NINV;i++){ const cb = $("invequip-"+i), nm = ($("invname-"+i).value||"").trim(); if(!cb || !cb.checked || !nm) continue;
    const d = txt[nm]; if(!d) continue;
    const r = limitedFromText(nm, d); if(r) addLimitedRow(r.name, r.max, r.rec, d.slice(0,300));
  }
}

