async function reloadAllBooks(){   // one click: re-fetch every loaded book to refresh its data
  const names = loadedBooks(); if(!names.length){ flashStatus("No loaded books to reload"); return; }
  const base = ($("server-url").value || "").trim() || "http://localhost:5050";
  const btn = $("btn-reload-all"), orig = btn ? btn.textContent : "";
  if(btn){ btn.disabled = true; btn.textContent = "Reloading…"; }
  try{
    const bj = await fetch(base.replace(/\/+$/,"")+"/data/books.json").then(r => { if(!r.ok) throw 0; return r.json(); });
    const codeOf = {}; (bj.book||[]).forEach(b => { codeOf[String(b.name||b.id||"").toLowerCase()] = b.id||b.source; });
    let n = 0, missed = 0;
    for(const nm of names){ const code = codeOf[String(nm).toLowerCase()];
      if(!code){ missed++; continue; }
      mergeBook(DATA, await fetch5etoolsBook(base, code), nm); n++;
    }
    _spellIndex = null; bakeSourceData();
    try{ localStorage.setItem(SOURCES_KEY, JSON.stringify(DATA)); }catch(e){}
    populateWizard(); populateArmor(); renderSpellStyle(false); updateSourcebookStatus(); populateBookSelect(); populateMonsterList(); compute();
    flashStatus("Reloaded " + n + " source" + (n===1?"":"s") + (missed?" ("+missed+" not on server)":"") + " — data refreshed");
  }catch(e){ flashStatus("Reload failed — is your 5etools server running at "+base+"?"); }
  finally{ if(btn){ btn.disabled = false; btn.textContent = orig || "Reload all loaded sources"; } }
}

