let invDrag = null;
const invCols = document.querySelector(".inv-cols");
const clearDrop = () => invCols.querySelectorAll("tr.drop-target, tr.drop-into").forEach(r => r.classList.remove("drop-target","drop-into"));
invCols.addEventListener("click", e => {   // clicking a container's drag handle toggles its contents (dragging it still reorders)
  const c = e.target.closest(".invdrag.cont-toggle"); if(!c) return;
  const nm = c.dataset.cont; if(!nm) return;
  if(collapsedContainers.has(nm)) collapsedContainers.delete(nm); else collapsedContainers.add(nm);
  save(); renderContainers();
});
invCols.addEventListener("dragstart", e => {
  const h = e.target.closest(".invdrag"); if(!h){ e.preventDefault(); return; }
  invDrag = +h.closest("tr").dataset.r; e.dataTransfer.effectAllowed = "move"; try{ e.dataTransfer.setData("text/plain", String(invDrag)); }catch(_){}
});
invCols.addEventListener("dragover", e => {
  if(invDrag == null) return; e.preventDefault(); e.dataTransfer.dropEffect = "move";
  const tr = e.target.closest("tr"); clearDrop();
  if(tr){ const to = +tr.dataset.r;
    tr.classList.add((to !== invDrag && isContainerRow(to)) ? "drop-into" : "drop-target"); }   // onto a container = store inside it
});
invCols.addEventListener("drop", e => {
  if(invDrag == null) return; e.preventDefault();
  const tr = e.target.closest("tr");
  if(tr){ const to = +tr.dataset.r;
    if(isContainerRow(invDrag)){                                             // dragging a container → it carries its contents with it
      setRowCont(invDrag, (to !== invDrag && isContainerRow(to)) ? ($("invname-"+to).value||"").trim() : "");
      moveInvBlock(invDrag, to);
    } else if(to !== invDrag && isContainerRow(to)){                         // item onto a container → store inside + nest under it
      setRowCont(invDrag, ($("invname-"+to).value||"").trim());
      moveInvRow(invDrag, invDrag < to ? to : to+1);
    } else { setRowCont(invDrag, ""); moveInvRow(invDrag, to); }             // plain reorder (and pull it out of any container)
    save(); compute();                                                       // refresh even when moveInvRow/Block no-ops
  }
  clearDrop(); invDrag = null;
});
invCols.addEventListener("dragend", () => { clearDrop(); invDrag = null; });

