    const tab = document.querySelector('.ptab[data-page="'+key+'"]');
    if(tab){ tab.style.display = userHidden ? "none" : ""; tab.classList.toggle("muted", excluded && !userHidden); }
    const page = $("page-"+key);
    if(page) page.classList.toggle("excluded", excluded);
  });
  const active = document.querySelector(".page.active");          // active page hidden → jump to first visible
  if(active && active.classList.contains("excluded")){
    const firstKey = PAGES.map(p=>p[0]).find(k => { const pg=$("page-"+k); return pg && !pg.classList.contains("excluded"); });
    if(firstKey) showPage(firstKey);
  }
}

