// Split the Features box into {title, body} for the per-feature card view (separate from featureBlocks, which the
// limited-use detector uses — this one keeps the full body and drops the "Name. " lead-in for a clean card title).
function featureCards(){
  const v = ($("features").value||""); if(!v.trim()) return [];
  return v.split(/\n\s*\n+/).map(b => {
    const s = b.trim().replace(/^Feat:\s*/i, ""); if(!s) return null;
    const dot = s.indexOf(". "), par = s.indexOf(" (");
    let cut = -1, skip = 0;
    if(dot >= 0 && (par < 0 || dot < par)){ cut = dot; skip = 2; }   // "Rage. You can…" → title "Rage"
    else if(par >= 0){ cut = par; skip = 1; }                        // "Darkvision (60 ft)…" → title "Darkvision", keep the paren in the body
    if(cut < 0){ const nl = s.indexOf("\n"); return nl >= 0 ? {title:s.slice(0,nl).trim(), body:s.slice(nl+1).trim()} : {title:s, body:""}; }
    return {title:s.slice(0,cut).trim(), body:s.slice(cut+skip).trim()};
  }).filter(Boolean);
}
function renderFeatureCards(){
  const wrap = $("feat-cards"); if(!wrap) return;
