  const cls = sEl(inst,"spellclass").value;
  const multi = (((($("classlevel").value||"").match(/[A-Za-z'’][A-Za-z'’\- ]*?\s+\d+/g))||[]).length) > 1;
  const map = multi ? null : autoSlots(cls, charLevel());   // multiclass slots are manual (don't stack cleanly)
  for(let l=1;l<=9;l++){
    const tot = sEl(inst,"slot"+l); if(!tot) continue;
    if(map){ const c = map[l]; tot.value = (c != null) ? String(c) : ""; tot.readOnly = true; }
    else if(tot.readOnly){ tot.value = ""; tot.readOnly = false; }   // reverting to manual: clear the stale auto value, unlock
  }
}
function applySlotFilter(inst=0){              // show only slot levels the build can use (matches the spell list)
  const info = CASTERS[sEl(inst,"spellclass").value];
  const card = sEl(inst,"slots-card"); if(card) card.style.display = (info && info.noSlots) ? "none" : "";   // ki casters (Shadow Monk) use no slots
  for(let l=1;l<=9;l++){ const c = sEl(inst,"slotcell"+l); if(c) c.style.display = (l <= spellMaxByInst[inst]) ? "" : "none"; }
  refreshSpellSlots(inst);
}

