function spellRowSelect(l, i, cur, names){
  const lc = (cur||"").toLowerCase();
  const inList = names.some(n => n.toLowerCase() === lc);
  let o = `<option value=""></option>`;
  if(cur && !inList) o += `<option value="${esc(cur)}" selected>${esc(cur)} (off-list)</option>`;
  o += names.map(n => `<option value="${esc(n)}"${n.toLowerCase()===lc?" selected":""}>${esc(n)}</option>`).join("");
  return `<select class="sp-name" data-l="${l}" data-i="${i}">${o}</select>`;
}

