function hasSpellNamed(name){   // is this spell on ANY of the character's spell sheets (written rows or prepared list)?
  const q = String(name).trim().toLowerCase();
  for(let inst=0; inst<spellSheets; inst++){
    const SE = spellEntriesByInst[inst] || {};
    for(const l in SE){ if((SE[l]||[]).some(r => (r.name||"").trim().toLowerCase() === q)) return true; }
    const P = preparedByInst[inst] || {};
    for(const k in P){ if(P[k] && String(k).toLowerCase() === q) return true; }
  }
  return false;
}

