  const S = b => sx(inst, b);
  const manual = kind === "manual";
  const classOpts = `<option value=""></option>`+
    `<option>Artificer</option><option>Bard</option><option>Cleric</option><option>Druid</option>`+
    `<option>Fighter (Eldritch Knight)</option><option>Monk (Way of Shadow)</option>`+
    `<option>Paladin</option><option>Ranger</option><option>Rogue (Arcane Trickster)</option>`+
    `<option>Sorcerer</option><option>Warlock</option><option>Wizard</option><option value="Other">Other</option>`;
