    `<option value="cha">Cha</option><option value="str">Str</option><option value="dex">Dex</option><option value="con">Con</option>`;
  let lvlOpts = `<option value="">Character level</option>`;
  for(let l=1;l<=20;l++) lvlOpts += `<option value="${l}">${l}</option>`;
  const lvlField = manual
    ? `<div><label class="lbl">Class Level</label><select data-save id="${S('spelllevel')}" title="Level this sheet's slots, spell levels, and known/prepared counts are based on. 'Character level' follows your main level.">${lvlOpts}</select></div>`
