          `<div><label class="lbl">Spellcasting Class</label><select data-save id="${S('spellclass')}">${classOpts}</select></div>`+
          `<div><label class="lbl">Ability</label><select data-save id="${S('spellability')}">${abilOpts}</select></div>`+
          lvlField+

