function etTools(itemsBase, itemsData, SRC){   // AT/INS in items-base; GS/T (thieves' tools, kits, gaming sets) in items.json
  const set = new Set();
  (itemsBase.baseitem||[]).forEach(it => { if(it.source === SRC && ET_TOOL_TYPES.includes((it.type||"").split("|")[0])) set.add(it.name); });
  (itemsData.item||[]).forEach(it => { if(it.source === SRC && ET_TOOL_TYPES.includes((it.type||"").split("|")[0])) set.add(it.name); });
  return [...set].sort();
}
// Tools split by category (AT = artisan's tools, INS = musical instruments) so a generic "artisan's tools of
// your choice" / "musical instrument of your choice" grant can offer the right concrete options to pick from.
function etToolCats(itemsBase, itemsData, SRC){
  const cats = {artisan:new Set(), instrument:new Set()};
  const add = it => { if(it.source !== SRC) return; const t = (it.type||"").split("|")[0];
    if(t === "AT") cats.artisan.add(it.name); else if(t === "INS") cats.instrument.add(it.name); };
  (itemsBase.baseitem||[]).forEach(add); (itemsData.item||[]).forEach(add);
  return {artisan:[...cats.artisan].sort(), instrument:[...cats.instrument].sort()};
}

