// Matches the generic phrase only (not a trailing " (Source)" tag); specific tools like "Smith's Tools" never match.
const TOOLPICK_RE = /(\d+)?\s*(artisan['’]?s tools(?: of your choice)?|musical instruments?(?: of your choice)?|instruments?\s+of your choice)/ig;
let toolPickMatches = [];
function scanToolPicks(text){
  const out = []; let m; TOOLPICK_RE.lastIndex = 0;
  while((m = TOOLPICK_RE.exec(text))){
    const kind = /artisan/i.test(m[2]) ? "artisan" : "instrument";
    const opts = (DATA && DATA.toolCats && DATA.toolCats[kind]) || [];
    if(!opts.length) continue;                       // no concrete options available (book not loaded) → leave the text as-is
    out.push({start:m.index, end:m.index + m[0].length, kind, count:Math.max(1, parseInt(m[1],10) || 1)});
  }
  return out;
}
function resolveToolChoices(){     // open the picker if the Proficiencies box has any unresolved generic tool grants
  const p = $("proficiencies"); if(!p) return;
  toolPickMatches = scanToolPicks(p.value);
  if(!toolPickMatches.length) return;
  $("tool-list").innerHTML = toolPickMatches.map((m, mi) => {
    const opts = DATA.toolCats[m.kind], label = m.kind === "artisan" ? "Artisan's tools" : "Musical instrument";
    let rows = "";
    for(let c=0;c<m.count;c++){
      rows += `<div style="display:flex; align-items:center; gap:10px; margin:8px 0">`
        + `<span style="flex:1; font-weight:600; font-size:13px">${esc(label)}${m.count>1?" #"+(c+1):""}</span>`
        + `<select class="tool-pick" data-mi="${mi}" data-c="${c}" style="flex:1">`
        + opts.map(o => `<option value="${esc(o)}">${esc(o)}</option>`).join("") + `</select></div>`;
    }
    return rows;
  }).join("");
  $("toolmodal").classList.add("open");
}
function applyToolChoices(){
  const p = $("proficiencies"); if(!p){ $("toolmodal").classList.remove("open"); return; }
  const text = p.value;
  const chosen = toolPickMatches.map((m, mi) => {
    const names = [];
    for(let c=0;c<m.count;c++){ const sel = document.querySelector(`.tool-pick[data-mi="${mi}"][data-c="${c}"]`); if(sel) names.push(sel.value); }
    return names.join(", ");
  });
  let out = "", cursor = 0;                           // splice replacements in source order (matches are sorted, non-overlapping)
  toolPickMatches.forEach((m, mi) => { out += text.slice(cursor, m.start) + chosen[mi]; cursor = m.end; });
  out += text.slice(cursor);
  p.value = out; autoGrow(p);
  toolPickMatches = [];
  $("toolmodal").classList.remove("open");
  save(); compute();
}
