export const meta = {
  name: 'dnd-sheet-source-audit',
  description: 'Audit the D&D sheet extraction + calc handling across the loaded 5etools sources',
  phases: [{ title: 'Audit', detail: 'parallel dimension auditors vs the live 5etools server + the sheet code' }],
}

const SHEET = '/Users/alexhedtke/Documents/dnd-character-sheet/Character Sheet.html'
const SERVER = 'http://localhost:5050'

const SCHEMA = { type:'object', additionalProperties:false, properties:{
  dimension:{type:'string'},
  summary:{type:'string'},
  gaps:{type:'array', items:{type:'object', additionalProperties:false, properties:{
    area:{type:'string', description:'short tag, e.g. "Natural Armor"'},
    detail:{type:'string', description:'what is wrong/missing, naming the entities + book(s)'},
    severity:{type:'string', enum:['high','medium','low']},
    fix:{type:'string', description:'concrete suggested change to the sheet/extractor'}
  }, required:['area','detail','severity','fix']}}
}, required:['dimension','summary','gaps'] }

const common = `You are auditing a single self-contained D&D 5e (2014 rules) character sheet at:
${SHEET}
It loads 5etools JSON from a local server at ${SERVER}/data/ and extracts a trimmed subset in the browser via functions named et* (etRaces, etSkills, etProfBlock, etNormProf, etClasses, etFeats, etc.), mirrored by build-data.py. The sheet deliberately FILTERS OUT 2024 books (source codes XPHB / XDMG / XMM) — ignore those. Consider the 2014 player-facing books present on the server (PHB, XGE, TCE/Tasha, SCAG, VGM, MTF, MPMM, ERLW, GGR, MOT, FTD, EGW, AAG, SCC, BGG, plus DMG for items).

Method: use Grep/Read on the sheet file to see exactly how the extractor and the consumers handle your dimension, AND fetch the relevant raw data with curl (e.g. \`curl -s ${SERVER}/data/races.json\`, \`curl -s ${SERVER}/data/class/index.json\` then the per-class files, \`curl -s ${SERVER}/data/backgrounds.json\`, \`curl -s ${SERVER}/data/feats.json\`). Compare what the sheet does against what the rules require, and report CONCRETE gaps that would make a character built from these books wrong or incomplete on the sheet. Name the specific entities and books. Do NOT edit any files — report findings only. Prefer high-impact, systemic gaps (patterns affecting many entities) over one-off oddities.`

const dims = [
  { label:'audit:abilities', focus:`ABILITY SCORES. How race ability bonuses are extracted (etRaces 'ability' handling) and applied (applyRace; the wizard "Ability Scores" step pre-fills the Racial column). Check: fixed bonuses; "choose" floating bonuses (e.g. Half-Elf, Variant Human); races with NO ability block at all (MPMM/Tasha "assign +2/+1 freely" — ~83 races); any "weighted" ability format. Do bonuses land correctly in the Racial column? Are choice/floating ones surfaced so the player knows to assign them? Is anything silently dropped or double-counted?` },
  { label:'audit:proficiencies', focus:`SKILL / TOOL / LANGUAGE proficiencies. Look at etSkills, etProfBlock, etNormProf, renderWizSkills, applyProficiencies, ET_ANY_LABELS. NOTE: the "any N skills" class case was just fixed (renderWizSkills now falls back to all 18 skills when count>0 and the from-list is empty). Audit the rest: tool & language "any"/"anyProficiency"/"choose" choices across races, backgrounds, and classes — are they selectable or only shown as static text? Any choices that render blank/empty? Expertise (Rogue/Bard) handling? Report systemic misses.` },
  { label:'audit:ac-calc', focus:`SPECIAL AC & OTHER CALCULATIONS. The compute() AC block only auto-handles Unarmored Defense for Barbarian (10+Dex+Con) and Monk (10+Dex+Wis) when "Unarmored" is selected. Enumerate races/subclasses across the loaded books that SET or MODIFY AC and aren't handled, with the EXACT formula + source: Natural Armor races (Lizardfolk, Tortle, Loxodon, Locathah, Troglodyte, etc.), Warforged Integrated Protection (+1), Draconic Sorcerer Draconic Resilience (13+Dex), and any others. Also flag other special calcs: alternate speeds, and HP-per-level boosters (Hill Dwarf, Draconic Resilience, Tough feat — note HP is entered manually so these may be out of scope). Recommend how to add the AC ones (e.g. a race-keyed natural-armor map applied in the Unarmored branch).` },
  { label:'audit:spellcasting', focus:`SPELLCASTING coverage. Look at CASTERS, SUB_CANTRIPS, SPELL_LIST_FROM, classSpellList, classSpellNamesAt, etClassSpells/classVariant, and how createCharacter adds a subclass's always-prepared spells. Check across loaded books: (a) subclass casters beyond Eldritch Knight / Arcane Trickster that need a borrowed/limited list; (b) always-prepared or expanded spell lists from subclasses (Cleric domains, Druid circles, Paladin oaths, Warlock patrons, Sorcerer Aberrant Mind / Clockwork Soul, Ranger archetypes, Artificer specialists) — does the sheet surface them; (c) Artificer's own spell list (it's scattered across books); (d) races that grant innate/cantrip spells (High Elf, Tiefling, Drow, etc.) — are they captured anywhere. Report coverage gaps.` },
  { label:'audit:limited-use', focus:`LIMITED-USE RESOURCES (the Limited Features tracker: Feature / Max / Recover / Used). Look at LIMITED_RESOURCES (class-wide entries with computed counts), fillLimitedFeatures, the text heuristic limitedFromText, refreshLimitedFeatures, and LIMITED_OVERRIDES / LIMITED_EXCLUDE. Across CLASSES and especially SUBCLASSES in the loaded books, list X-per-rest / X-per-day features that are NOT auto-added, or are added with the wrong Max or Recover. Focus on common patterns: Channel Divinity options, additional Wild Shape uses, sorcerer/warlock/cleric subclass dice or pools, racial once-per-rest traits (e.g. Breath Weapon, Relentless Endurance, Fey Step, Healing Hands). Recommend which deserve curated entries vs. heuristic tweaks.` },
  { label:'audit:senses-speed-feats', focus:`SENSES / SPEED / RESISTANCES / RACE-GRANTED FEATS. Look at etRaces (trait parsing into senses, darkvision, langChoose, variableSkillDarkvision, resist, speed) and applyRace; plus raceFeatGrants / etFeatGrants and the ASI/feat flag. Check across loaded races: darkvision values incl. 120 ft (Drow) and superior darkvision; blindsight/tremorsense; ALTERNATE SPEEDS (fly, swim, climb, burrow — e.g. Aarakocra fly 50, Triton/merfolk swim, Tabaxi climb) — are they captured into the Senses/Speed boxes; damage resistances (r.resist); and which races GRANT A FEAT (Variant Human, Custom Lineage, and any others) — does the feat-slot counter include them. Report misses with the fix.` },
]

phase('Audit')
const results = await parallel(dims.map(d => () =>
  agent(common + '\n\nYOUR DIMENSION — ' + d.focus, { label: d.label, schema: SCHEMA })
))
return results.filter(Boolean)

