function disabledBooks(){ return new Set((DATA && DATA._meta && DATA._meta.disabled) || []); }
function hasAllRaw(){                          // do we have per-book data for every loaded book? (needed to filter)
  const m = DATA && DATA._meta; if(!m) return false; const raw = m.raw || {};
  return (m.books || []).length > 0 && (m.books || []).every(nm => raw[nm]);
}
function rebuildFromRaw(){                      // rebuild the merged DATA from only the ENABLED per-book data
  const m = DATA._meta, order = (m.books || []).slice(), off = disabledBooks();
  const fresh = {_meta:{books:[], dataVersion:m.dataVersion}};
  order.forEach(nm => { if(!off.has(nm) && m.raw && m.raw[nm]) mergeBook(fresh, m.raw[nm], nm); });
  fresh._meta.books = order;                    // keep the full known-book list (incl. hidden) so the filter UI still lists them
  fresh._meta.disabled = Array.from(off);
  fresh._meta.raw = m.raw;
  if(m.dataVersion != null) fresh._meta.dataVersion = m.dataVersion;
  DATA = fresh; _spellIndex = null;
}
function persistSources(){                      // save merged DATA (lean) + per-book raw, separately so quota issues can't lose both
  if(!DATA){ try{ localStorage.removeItem(SOURCES_KEY); localStorage.removeItem(SOURCES_RAW_KEY); }catch(e){} return; }
  const raw = DATA._meta && DATA._meta.raw; if(raw) delete DATA._meta.raw;   // keep the merged copy lean
  let ok = true;
  try{ localStorage.setItem(SOURCES_KEY, JSON.stringify(DATA)); }catch(e){ ok = false; }
  finally{ if(raw) DATA._meta.raw = raw; }
  if(raw){ try{ localStorage.setItem(SOURCES_RAW_KEY, JSON.stringify(raw)); }catch(e){} }
  return ok;
}
function refreshAfterData(){                     // one call to re-render everything that reads DATA
  populateWizard(); populateArmor(); populateItemList(); renderAllSpellSheets(false);
  updateSourcebookStatus(); populateBookSelect(); populateMonsterList(); renderLoadedBookList(); compute();
}
function renderLoadedBookList(){
  const el = $("loaded-books"); if(!el) return;
  const names = loadedBooks(); const off = disabledBooks();
  if(!names.length){ el.innerHTML = ""; return; }
  el.innerHTML = `<label class="lbl" style="display:block; margin:14px 0 4px">Loaded sources <span class="wiz-hint" style="font-weight:400; display:inline">— uncheck to hide a book's content</span></label>` +
    names.slice().sort((a,b)=>String(a).localeCompare(String(b))).map(nm =>
      `<label class="lay-row"><input type="checkbox" class="book-toggle" data-book="${esc(nm)}" ${off.has(nm)?"":"checked"}> ${esc(nm)}</label>`
    ).join("");
}
async function toggleBook(name, enabled){
  if(!DATA || !DATA._meta) return;
  const prev = (DATA._meta.disabled || []).slice();
  const set = new Set(prev); if(enabled) set.delete(name); else set.add(name);
  DATA._meta.disabled = Array.from(set);
  if(hasAllRaw()){ rebuildFromRaw(); bakeSourceData(); refreshAfterData(); persistSources();
    flashStatus(enabled ? name+" shown" : name+" hidden"); return;
  }
  flashStatus("Fetching source data to enable filtering…");
  const ok = await reloadAllBooks(true);        // re-fetch all books to populate per-book data, then re-applies the filter
  if(!ok){ DATA._meta.disabled = prev; renderLoadedBookList(); }   // server unreachable — revert the toggle
  else flashStatus(enabled ? name+" shown" : name+" hidden");
}

