async function reloadAllBooks(silent){   // one click: re-fetch every loaded book to refresh its (per-book) data, then re-apply the filter
  const names = loadedBooks(); if(!names.length){ if(!silent) flashStatus("No loaded books to reload"); return false; }
  const base = ($("server-url").value || "").trim() || "http://localhost:5050";
  const btn = $("btn-reload-all"), orig = btn ? btn.textContent : "";
  if(btn){ btn.disabled = true; btn.textContent = "Reloading…"; }
  try{
    const bj = await fetch(base.replace(/\/+$/,"")+"/data/books.json").then(r => { if(!r.ok) throw 0; return r.json(); });
    const codeOf = {}; (bj.book||[]).forEach(b => { codeOf[String(b.name||b.id||"").toLowerCase()] = b.id||b.source; });
    DATA._meta.raw = DATA._meta.raw || {};
    let n = 0, missed = 0;
    for(const nm of names){ const code = codeOf[String(nm).toLowerCase()];
      if(!code){ missed++; continue; }                              // not on this server — keep any prior per-book copy
      DATA._meta.raw[nm] = await fetch5etoolsBook(base, code); n++;
    }
    rebuildFromRaw(); bakeSourceData(); persistSources(); refreshAfterData();
    if(!silent) flashStatus("Reloaded " + n + " source" + (n===1?"":"s") + (missed?" ("+missed+" not on server)":"") + " — data refreshed");
    return true;
  }catch(e){ flashStatus("Reload failed — is your 5etools server running at "+base+"?"); return false; }
  finally{ if(btn){ btn.disabled = false; btn.textContent = orig || "Reload all loaded sources"; } }
}
async function loadAllBooks(){   // one click: import every available 2014 book not already loaded
  const base = ($("server-url").value || "").trim() || "http://localhost:5050";
  const btn = $("btn-loadall"), orig = btn ? btn.textContent : "";
  if(btn){ btn.disabled = true; btn.textContent = "Loading…"; }
  try{
    const bj = await fetch(base.replace(/\/+$/,"")+"/data/books.json").then(r => { if(!r.ok) throw 0; return r.json(); });
    const loaded = new Set(loadedBooks().map(n => String(n).toLowerCase()));
    const fresh = (bj.book||[]).filter(b => !isBook2024(b) && !loaded.has(String(b.name||b.id||"").toLowerCase()));
    if(!fresh.length){ flashStatus("All available books are already loaded"); return; }
    let n = 0;
    for(const b of fresh){
      if(btn) btn.textContent = `Loading ${n+1}/${fresh.length}…`;
      await doLoadBook(b.id||b.source, b.name||b.id, false, null);   // captures raw, merges, persists, refreshes each time
      n++;
    }
    flashStatus("Loaded " + n + " book" + (n===1?"":"s") + " — use “Save data file” to bake them into your sheet");
  }catch(e){ flashStatus("Load all failed — is your 5etools server running at "+base+"?"); }
  finally{ if(btn){ btn.disabled = false; btn.textContent = orig || "Load all books"; } }
}

