### 4. `applyClass()` & Proficiency Application (lines 3393–3407)

```javascript
function applyClass(name){
  populateSubclass(name);
  const c = DATA && findBy(DATA.classes,name);
  if(c){
    const lvl = charLevel();
    $("classlevel").value = name+" "+lvl;
    ABKEYS.forEach(k=>{ const box=$("savep-"+k); if(box) box.checked = c.saves.includes(k); });
