function applyProficiencies(prof, label){
  if(!prof) return;
  const tag = label ? ` (${label})` : "";
  (prof.skills||[]).forEach(s => { const box = $("skp-"+(SKILL_KEY[s]||s)); if(box) box.checked = true; });
  const lines = [];
  if(prof.skillChoose){ const f = (prof.skillChoose.from||[]).map(_titlecase); lines.push("Skills: choose " + prof.skillChoose.count + (f.length ? " (" + f.join(", ") + ")" : "")); }
  if(prof.weapons)   lines.push("Weapons: " + prof.weapons.join(", "));
  if(prof.armor)     lines.push("Armor: " + prof.armor.join(", "));
  if(prof.tools)     lines.push("Tools: " + prof.tools.join(", "));
  if(prof.other)     lines.push("Proficiencies: " + prof.other.join(", "));
  if(lines.length){ const p = $("proficiencies"); const block = lines.map(l => l + tag).join("\n"); p.value = p.value.trim() ? p.value + "\n" + block : block; autoGrow(p); }
  if(prof.languages) addLanguages(prof.languages);
}
