function refreshSpellSlots(inst=0){
  const cls = sEl(inst,"spellclass").value;
  const multi = inst ? false : (((($("classlevel").value||"").match(/[A-Za-z''][A-Za-z''\- ]*?\s+\d+/g))||[]).length) > 1;
  const map = multi ? null : autoSlots(cls, sheetLevel(inst));  // multiclass slots are MANUAL
  for(let l=1;l<=9;l++){
    const tot = sEl(inst,"slot"+l); if(!tot) continue;
    if(map){ const c = map[l]; tot.value = (c != null) ? String(c) : ""; tot.readOnly = true; }
    else if(tot.readOnly){ tot.value = ""; tot.readOnly = false; }  // reverting to manual: clear stale auto value, unlock
  }
}
```

**Spell Progression Tables** (lines 2466–2482):
- `SLOTS_FULL`: full casters (Bard, Cleric, Druid, Sorcerer, Wizard)
- `SLOTS_HALF`: half casters (Paladin, Ranger)
- `SLOTS_ARTIFICER`: half but rounds up (starts at level 1)
- `SLOTS_THIRD`: one-third casters (Fighter EK, Rogue AT)

**autoSlots()** (lines 2470–2481):
```javascript
function autoSlots(cls, lvl){  // -> {spellLevel: count} for a known single-class caster, {} if no slots yet, null if manual
  if(lvl == null) return null;
  const L = Math.min(20, Math.max(1, lvl));
  if(cls === "Warlock"){ const cnt = L>=17?4:L>=11?3:L>=2?2:1, lev = L>=9?5:Math.ceil(L/2); return {[lev]:cnt}; }
  let tbl = null;
  if(["Bard","Cleric","Druid","Sorcerer","Wizard"].includes(cls)) tbl = SLOTS_FULL;
  else if(["Paladin","Ranger"].includes(cls)) tbl = SLOTS_HALF;
  else if(cls === "Artificer") tbl = SLOTS_ARTIFICER;
  else if(THIRD_CASTERS.includes(cls)) tbl = SLOTS_THIRD;
  if(!tbl) return null;
  const row = tbl[L]; if(!row) return {};
  const map = {}; row.forEach((c,i) => { if(c) map[i+1] = c; }); return map;
}
```

**Current Multiclass Handling:** Sheet 0 (main Spells page) detects multiclass and **forces manual slots** (reads/writes from user input, no auto-fill). Extra spell sheets (inst > 0) can override the class and use their own single-class progression. **No stacking logic exists** — the sheet explicitly punts on multiclass slot math.

