  saves: [ability keys],                                 // e.g. ["str", "con"]
  skillChoose: {count: number, from: [skill names]} | undefined,
  skillsFixed: [skill names] | undefined,               // always-gained skills
  prof: {                                                // proficiencies
    skills: [skill names] | undefined,
    skillChoose: {count, from} | undefined,
    weapons: [weapon names],
    armor: [armor names],
    tools: [tool names],
    languages: [language names],
    other: [other proficiency strings]
  },
  armor: [armor name strings],                           // redundant; from prof.armor
  weapons: [weapon name strings],                        // redundant; from prof.weapons
  casterAbility: "int"|"wis"|"cha" | undefined,        // spellcasting ability (if applicable)
  casterProgression: "full"|"half"|"third" | undefined, // spell progression type
  cantrips: [count per level] | null,                   // cantripProgression array (20 elements for levels 1–20)
  spellsKnown: [count per level] | null,                // spellsKnownProgression array (for known-list casters)
  equip: {
    items: [equipment choice strings],                   // "weapon: shortsword or dagger", etc.
    gold: string                                         // e.g. "5d4*10"
  },
  features: [
    {name: string, level: 1–20, text: string}           // class features at each level
  ],
  subclassTitle: string,                                 // e.g. "Subclass", "Archetype", "Oath"
  subclassLevel: number,                                 // level at which subclass is chosen (usually 1 or 3)
  subclasses: [
    {
      name: string,
      short: string,
      features: [{name, level, text, opt, optGroup}],   // opt = feature is a "choose one" option; optGroup = its category
      spells: [{n: name, l: level}],                    // always-prepared/granted spells
      expanded: [{n: name, l: level}],                  // expanded spell list (Warlock patron, etc.)
      featChoices: [
        {label: string, options: [names], levels: [numbers]}  // "choose one of these options" pickers
      ]
    }
  ]
}
