function buildClassLevelStr(list){ return (list||[]).map(c => `${c.name} ${c.level}${c.sub?` (${c.sub})`:""}`).join(", "); }
function reqStr(req){          // "Str 13", "Str 13 or Dex 13", "Str 13 and Cha 13"
  if(!req) return "";
  const one = o => Object.keys(o).filter(k => ABBR[k]).map(k => ABBR[k]+" "+o[k]).join(" and ");
  return (req.or ? req.or.map(one) : [one(req)]).filter(Boolean).join(" or ");
}
function mcReqMet(req){        // does the wizard's current ability spread satisfy this multiclass prereq?
  if(!req) return true;
  const ok = o => Object.keys(o).filter(k => ABBR[k]).every(k => (finalScore(k) || 0) >= o[k]);
  return req.or ? req.or.some(ok) : ok(req);
}
function syncBuildToSheet(){   // keep #classlevel live so the existing ASI engine + flag work while building
