function createCharacter(){
  const name=$("wiz-name").value.trim(), race=$("wiz-race").value, cls=$("wiz-class").value,
        sub=$("wiz-subclass").value, lvl=Math.min(20,Math.max(1,num($("wiz-level").value,1))), bg=$("wiz-bg").value;
  const chosenOpts = new Set();                                                // subclass "choose one" picks (e.g. Totem Spirit → Bear) — read NOW, before applyClass rebuilds the wizard selects
  document.querySelectorAll(".wiz-subchoice").forEach(s => { if(s.value) chosenOpts.add(s.value); });
  // proficiencies become authoritative for the new build
  document.querySelectorAll('#saves input[type="checkbox"], #skills input[type="checkbox"]').forEach(c=>c.checked=false);
  asiChoices = []; asiFeatsAdded = {}; bonusVals.asi = zeroAb();   // new build → unassigned ASIs, flagged for the player
  if(name) $("charname").value = name;
  if(race){
    const rObj = findBy(DATA.races, race), opts = {keepRacial:true, languages:[...document.querySelectorAll(".rc-lang")].map(s => s.value).filter(Boolean)};   // keep the Racial column the wizard's Under-the-Hood step already set (incl. the player's choose picks)
    if(rObj && rObj.variableSkillDarkvision){
      const useDv = (document.querySelector('input[name="rc-skilldv"]:checked')||{}).value === "darkvision";
      if(useDv) opts.darkvision = rObj.darkvision || 60; else opts.skill = ($("rc-skill")||{}).value || "";
    }
    applyRace(race, opts);
  }
  if(cls){
    applyClass(cls);
    const c = findBy(DATA.classes, cls);
    $("classlevel").value = cls + " " + lvl + (sub ? ` (${sub})` : "");
    if(c && c.hd){ hitDieFaces = c.hd; $("hd-total").value = lvl; }
    const subKey = (cls && sub) ? `${cls} (${sub})` : null;                   // subclass casters keyed "Class (Subclass)" (e.g. Monk (Way of Shadow))
    const spellKey = (subKey && CASTERS[subKey]) ? subKey : (CASTERS[cls] ? cls : null);
    if(spellKey){ $("spellclass").value = spellKey; renderSpellStyle(true, 0); }   // tailor the (primary) spell sheet
    document.querySelectorAll(".wiz-skill-cb:checked").forEach(cb => { const box = $("skp-"+cb.value); if(box) box.checked = true; });   // chosen class skills
    if(c && c.features && c.features.length){                                    // class features up to this level → Features page
      const cf = c.features.filter(f => (f.level||1) <= lvl);
      const lines = cf.map(f => `${f.name} (${cls} ${f.level}). ${f.text}`);
      if(lines.length){ const t = $("features"); const block = lines.join("\n\n"); t.value = t.value.trim() ? t.value+"\n\n"+block : block; autoGrow(t); }
      cf.forEach(f => { const s = FEATURE_SENSES[(f.name||"").toLowerCase()]; if(s) addSense(s); });   // e.g. Barbarian Danger Sense
    }
    const subObj = (c && sub) ? (c.subclasses||[]).find(x => x.name === sub) : null;   // chosen subclass → its features + always-prepared spells
    if(subObj){
      const subFeats = (subObj.features||[]).filter(f => (f.level||1) <= lvl && (!f.opt || chosenOpts.has(f.opt)));   // hide un-chosen option features (other totems)
      const sfl = subFeats.map(f => `${f.opt ? (f.optGroup ? f.optGroup+": " : "")+f.name : f.name} (${sub} ${f.level}). ${f.text}`);
      subFeats.forEach(f => { const s = FEATURE_SENSES[(f.name||"").toLowerCase()]; if(s) addSense(s); });
      const sInfo = spellKey && CASTERS[spellKey];
      if(subObj.spells && subObj.spells.length){
        sfl.push(`${sub} spells (always prepared): ${subObj.spells.map(sp => sp.n).join(", ")}.`);
        if(sInfo && sInfo.fullList) subObj.spells.forEach(sp => { preparedByInst[0][sp.n] = true; });        // tick the prep box on the pre-filled list
        else if(sInfo) subObj.spells.forEach(sp => { const l = Math.min(9, Math.max(0, sp.l||0)), arr = (spellEntriesOf(0)[l] = spellEntriesOf(0)[l] || []);
          if(!arr.some(r => (r.name||"").toLowerCase() === sp.n.toLowerCase())) arr.push({name:sp.n, prep:true}); });   // write-in caster → add as a prepared row
      }
      if(subObj.expanded && subObj.expanded.length)
        sfl.push(`${sub} expanded spells (added to your spell list): ${[...new Set(subObj.expanded.map(sp => sp.n))].join(", ")}.`);
      if(sfl.length){ const t = $("features"); const block = sfl.join("\n\n"); t.value = t.value.trim() ? t.value+"\n\n"+block : block; autoGrow(t); }
      if(spellKey) renderSpellStyle(false, 0);   // reflect the always-prepared subclass spells on the Spells page
    }
    const featMap = {};                                                          // feature name → text, for limited-use tooltips
    (c && c.features || []).forEach(f => { featMap[(f.name||"").toLowerCase()] = f.text; });
    (subObj && subObj.features || []).forEach(f => { featMap[(f.name||"").toLowerCase()] = f.text; });
    fillLimitedFeatures(cls, lvl, featMap);                                       // Ki / Sorcery Points / Rage / Channel Divinity → Limited Features card
    const eq = (c && c.equip) || {};                                            // starting gold OR equipment
    if(wizEquip === "gold"){ const g = goldAverage(eq.gold); if(g != null) $("gp").value = g; }
    else (eq.items||[]).forEach((line,i) => {                                    // resolve each choice (weapons/packs) → Inventory rows
      const p = parseEquipLine(line), lineEl = document.querySelector(`.equip-line[data-i="${i}"]`);
      const pick = lineEl && lineEl.querySelector(".equip-pick");
      const opt = p.fixed ? p.text : (pick ? pick.value : (p.options[0]||""));
      resolveEquipOption(opt, lineEl).forEach(e => addInvItem(e.name, e.qty));
    });
  }

