function createCharacter(){
  const name=$("wiz-name").value.trim(), race=$("wiz-race").value, bg=$("wiz-bg").value;
  const list = wizClasses.slice();                                             // the multiclass build; list[0] is the initial class
  // proficiencies become authoritative for the new build
  document.querySelectorAll('#saves input[type="checkbox"], #skills input[type="checkbox"]').forEach(c=>c.checked=false);
  if(name) $("charname").value = name;
  if(race){
    const rObj = findBy(DATA.races, race), opts = {keepRacial:true, languages:[...document.querySelectorAll(".rc-lang")].map(s => s.value).filter(Boolean)};   // keep the Racial column the wizard's Under-the-Hood step already set (incl. the player's choose picks)
    if(rObj && rObj.variableSkillDarkvision){
      const useDv = (document.querySelector('input[name="rc-skilldv"]:checked')||{}).value === "darkvision";
      if(useDv) opts.darkvision = rObj.darkvision || 60; else opts.skill = ($("rc-skill")||{}).value || "";
    }
    applyRace(race, opts);
  }
  if(list.length){
    const c0 = findBy(DATA.classes, list[0].name), totalLevel = list.reduce((a,w)=>a+w.level, 0);
    $("classlevel").value = buildClassLevelStr(list);
    if(c0) ABKEYS.forEach(k=>{ const box=$("savep-"+k); if(box) box.checked = c0.saves.includes(k); });   // saving-throw profs come from the INITIAL class only
    if(list.length === 1 && c0 && c0.hd){ hitDieFaces = c0.hd; $("hd-total").value = list[0].level; }     // single class → "1dX+CON" heal box
    else { hitDieFaces = null; $("hd-total").value = totalLevel;                                          // multiclass → mixed pools as text (compute() leaves #hitdice alone when faces=null)
      const pools = list.map(w => { const c=findBy(DATA.classes,w.name); return (c&&c.hd) ? `${w.level}d${c.hd}` : ""; }).filter(Boolean);
      if(pools.length) $("hitdice").value = pools.join(", "); }
    list.forEach((w,idx) => { const c=findBy(DATA.classes,w.name); if(c) applyProficiencies(idx===0 ? c.prof : c.mcProf, w.name); });   // initial = full; secondary = multiclass subset
    document.querySelectorAll(".wiz-skill-cb:checked").forEach(cb => { const box = $("skp-"+cb.value); if(box) box.checked = true; });   // initial-class skill picks
    let primary=null, primaryLvl=-1;                                            // primary spell sheet = the highest-level caster class
    list.forEach(w => { const subKey = w.sub ? `${w.name} (${w.sub})` : null; const key = (subKey && CASTERS[subKey]) ? subKey : (CASTERS[w.name] ? w.name : null);
      if(key && w.level > primaryLvl){ primary = key; primaryLvl = w.level; } });
    if(primary){ $("spellclass").value = primary; renderSpellStyle(true, 0); }
    const sInfo = primary && CASTERS[primary], featLines = [];
    list.forEach(w => {
