      cf.forEach(f => { const s = FEATURE_SENSES[(f.name||"").toLowerCase()]; if(s) addSense(s); });   // e.g. Barbarian Danger Sense
      const subObj = w.sub ? (c.subclasses||[]).find(x => x.name === w.sub) : null;
      if(subObj){
        const opts = new Set(Object.values(w.subOpts||{}).filter(Boolean));     // chosen "choose one" options (e.g. Totem Spirit → Bear)
        const sf = (subObj.features||[]).filter(f => (f.level||1) <= w.level && (!f.opt || opts.has(f.opt)));
        sf.forEach(f => featLines.push(`${f.opt ? (f.optGroup ? f.optGroup+": " : "")+f.name : f.name} (${w.sub} ${f.level}). ${f.text}`));
        sf.forEach(f => { const s = FEATURE_SENSES[(f.name||"").toLowerCase()]; if(s) addSense(s); });
        if(subObj.spells && subObj.spells.length){
          featLines.push(`${w.sub} spells (always prepared): ${subObj.spells.map(sp => sp.n).join(", ")}.`);
          if(sInfo && sInfo.fullList) subObj.spells.forEach(sp => { preparedByInst[0][sp.n] = true; });
          else if(sInfo) subObj.spells.forEach(sp => { const l = Math.min(9, Math.max(0, sp.l||0)), arr = (spellEntriesOf(0)[l] = spellEntriesOf(0)[l] || []);
            if(!arr.some(r => (r.name||"").toLowerCase() === sp.n.toLowerCase())) arr.push({name:sp.n, prep:true}); });
        }
        if(subObj.expanded && subObj.expanded.length)
          featLines.push(`${w.sub} expanded spells (added to your spell list): ${[...new Set(subObj.expanded.map(sp => sp.n))].join(", ")}.`);
      }
      const featMap = {};                                                       // feature name → text, for limited-use tooltips
      (c.features||[]).forEach(f => { featMap[(f.name||"").toLowerCase()] = f.text; });
      (subObj && subObj.features || []).forEach(f => { featMap[(f.name||"").toLowerCase()] = f.text; });
      fillLimitedFeatures(w.name, w.level, featMap);                            // Rage / Ki / Sorcery Points / Channel Divinity → Limited Features card
    });
    if(featLines.length){ const t = $("features"); const block = featLines.join("\n\n"); t.value = t.value.trim() ? t.value+"\n\n"+block : block; autoGrow(t); }
    if(primary) renderSpellStyle(false, 0);                                      // reflect always-prepared subclass spells on the Spells page
    const eq = (c0 && c0.equip) || {};                                          // starting gear / gold comes from the INITIAL class only
    if(wizEquip === "gold"){ const g = goldAverage(eq.gold); if(g != null) $("gp").value = g; }
    else (eq.items||[]).forEach((line,i) => {
      const p = parseEquipLine(line), lineEl = document.querySelector(`.equip-line[data-i="${i}"]`);
      const pick = lineEl && lineEl.querySelector(".equip-pick");
      const opt = p.fixed ? p.text : (pick ? pick.value : (p.options[0]||""));
      resolveEquipOption(opt, lineEl).forEach(e => addInvItem(e.name, e.qty));
    });
  }

