function parseClassLevels(str){                // "Fighter 5 (Eldritch Knight), Wizard 3" → [{name,level,sub}]
  const out = [];
  String(str||"").split(",").forEach(seg => { const m = seg.match(/^\s*(.+?)\s+(\d+)\s*(?:\(([^)]+)\))?\s*$/);
    if(m) out.push({name:m[1].trim(), level:parseInt(m[2],10), sub:(m[3]||"").trim()}); });
  return out;
}
function multiclassCasterLevel(){              // PHB combined caster level (Warlock pact magic excluded — it's its own pool)
  let lvl = 0;
  parseClassLevels($("classlevel").value).forEach(c => {
    if(["Bard","Cleric","Druid","Sorcerer","Wizard"].includes(c.name)) lvl += c.level;        // full casters
    else if(["Paladin","Ranger"].includes(c.name)) lvl += Math.floor(c.level/2);              // half casters (round down)
    else if(c.name === "Artificer") lvl += Math.ceil(c.level/2);                              // Artificer rounds up
    else if(/eldritch knight|arcane trickster/i.test(c.sub)) lvl += Math.floor(c.level/3);    // one-third casters
  });
  return lvl;
}
function mcSlots(){                            // combined multiclass slot row from SLOTS_FULL, indexed by combined caster level
  const L = Math.min(20, multiclassCasterLevel()); if(L < 1) return {};
  const row = SLOTS_FULL[L] || []; const map = {}; row.forEach((c,i) => { if(c) map[i+1] = c; }); return map;
}
function refreshSpellSlots(inst=0){            // auto-fill (and lock) the Total boxes for a known single-class caster
  const cls = sEl(inst,"spellclass").value;
