  const multi = inst ? false : (((($("classlevel").value||"").match(/[A-Za-z'’][A-Za-z'’\- ]*?\s+\d+/g))||[]).length) > 1;
  let map;
  if(!multi) map = autoSlots(cls, sheetLevel(inst));
  else if(cls === "Warlock"){ const wl = (parseClassLevels($("classlevel").value).find(x => x.name === "Warlock")||{}).level || 0; map = autoSlots("Warlock", wl); }  // pact magic pool
  else map = mcSlots();                        // combined PHB multiclass spell slots

