async function doLoadBook(srcCode, bookName, reloading, btn, defer){   // shared by the load + reload pickers; defer=true skips the (expensive) finalize so a batch can do it once
  const base = ($("server-url").value || "").trim() || "http://localhost:5050";
  const orig = btn ? btn.textContent : "";
  if(btn){ btn.disabled = true; btn.textContent = reloading ? "Reloading…" : "Loading…"; }
  try{
    const data = await fetch5etoolsBook(base, srcCode);
    if(!DATA) DATA = {_meta:{books:[]}};
    DATA._meta.raw = DATA._meta.raw || {}; DATA._meta.raw[bookName] = data;   // keep per-book copy so it can be filtered out later
    if(DATA._meta.disabled) DATA._meta.disabled = DATA._meta.disabled.filter(n => n !== bookName);   // an explicit load (re)enables the book
    mergeBook(DATA, data, bookName);
    if(defer) return;   // batch loader finalizes once at the end
    if(finalizeSourceLoad() === false) flashStatus(bookName+" loaded (too large to save — stays this session)");
    else flashStatus(bookName + (reloading ? " reloaded (data refreshed)" : " loaded — use “Save data file” to bake it into your sheet"));
  }catch(e){ flashStatus((reloading?"Reload":"Load")+" failed — is your 5etools server running at "+base+"?"); }
  finally{ if(btn){ btn.disabled = false; btn.textContent = orig || "Load"; } }
}

