function hpAvg(die){ return Math.floor(die/2) + 1; }   // 5e fixed-HP average: d6→4, d8→5, d10→6, d12→7
function rollDie(die){ return 1 + (crypto.getRandomValues(new Uint32Array(1))[0] % die); }
function regenHp(mode, list){   // (re)build hpRolls for the given mode; level 1 is always max of the first class
  const dice = levelDiceFor(list); const prev = hpRolls.slice();
  hpRolls = dice.map((die,i) => {
