function _tidyDef(s){ return String(s).replace(/\s+damage\s*$/i, "").replace(/\s+/g, " ").trim().replace(/[,.]$/, "").slice(0, 90); }
function scanDefenses(text){   // pull "you have/gain resistance/immunity to X" out of feature prose → concise Resistances/Immunities lines (with any "while …" qualifier)
  const out = [];
  String(text||"").split(/(?<=[.;:])\s+/).forEach(raw => {
    const s = raw.trim(); let m;
    const cm = s.match(/^(while [^,]+?|when [^,]+?),/i), q = cm ? ` (${cm[1].toLowerCase()})` : "";
    if(m = s.match(/(?:you (?:have|gain|are granted)|gain|gains) resistance to ([^.;]+)/i)) out.push("Resistance: " + _tidyDef(m[1]) + q);
    if(m = s.match(/(?:you (?:have|gain)|gain) immunity to ([^.;]+)/i)) out.push("Immunity: " + _tidyDef(m[1]) + q);
    if(m = s.match(/you(?:'re| are) immune to ([^.;]+)/i)) out.push("Immune: " + _tidyDef(m[1]) + q);
  });
  return [...new Set(out)];
}

