// The same filtered dropdown as the search box, but on each inventory row's name input (fills THAT row; free text still allowed).
function setupInvAutocomplete(){
  const pop = $("inv-ac"); if(!pop) return;
  let cur = null, matches = [], sel = -1, suppress = false;
  const isInv = el => el && el.classList && el.classList.contains("invname-ac");
  const paint = () => { [...pop.querySelectorAll(".opt")].forEach((o,i) => o.classList.toggle("sel", i === sel)); const s = pop.querySelector(".opt.sel"); if(s) s.scrollIntoView({block:"nearest"}); };
  const position = () => { if(!cur) return; const r = cur.getBoundingClientRect(); pop.style.left = r.left+"px"; pop.style.top = r.bottom+"px"; pop.style.width = Math.max(r.width, 180)+"px"; };
  const close = () => { pop.hidden = true; pop.innerHTML = ""; matches = []; sel = -1; cur = null; };
  function render(inp){
    cur = inp; const q = (inp.value||"").trim().toLowerCase(); if(!q){ close(); return; }
    const names = (DATA && DATA.itemNames) || [], starts = [], contains = [];
    for(const n of names){ const i = n.toLowerCase().indexOf(q); if(i === 0) starts.push(n); else if(i > 0) contains.push(n); }
    matches = starts.concat(contains).slice(0, 200); sel = matches.length ? 0 : -1;
    if(!matches.length){ close(); cur = inp; return; }   // no match → hide list but keep the typed (free) text
    pop.innerHTML = matches.map((n,i) => { const w = itemWeight(n); return `<div class="opt${i===0?' sel':''}" data-i="${i}">${esc(n)}${w!=null?`<span class="w">${w} lb</span>`:''}</div>`; }).join("");
    pop.hidden = false; position();
  }
  function accept(name){ if(cur && name){ const inp = cur; suppress = true; inp.value = name; inp.dispatchEvent(new Event("input",{bubbles:true})); suppress = false; } close(); }
  document.addEventListener("input", e => { if(!suppress && isInv(e.target)) render(e.target); });
  document.addEventListener("focusin", e => { if(isInv(e.target)){ if((e.target.value||"").trim()) render(e.target); } else if(!e.target.closest("#inv-ac")) close(); });
  document.addEventListener("keydown", e => {
    if(!cur || pop.hidden || e.target !== cur) return;
    if(e.key === "ArrowDown"){ e.preventDefault(); sel = Math.min(sel+1, matches.length-1); paint(); }
    else if(e.key === "ArrowUp"){ e.preventDefault(); sel = Math.max(sel-1, 0); paint(); }
    else if(e.key === "Enter" && sel >= 0){ e.preventDefault(); accept(matches[sel]); }
    else if(e.key === "Escape"){ close(); }
  });
  pop.addEventListener("mousedown", e => { const o = e.target.closest(".opt"); if(o && o.dataset.i != null){ e.preventDefault(); accept(matches[+o.dataset.i]); } });
  document.addEventListener("focusout", e => { if(isInv(e.target)) setTimeout(() => { if(!pop.contains(document.activeElement)) close(); }, 120); });
  window.addEventListener("scroll", () => { if(!pop.hidden) close(); }, true);
}

