  const lvl = (d.level===0) ? (d.school ? d.school+" cantrip" : "Cantrip") : ("Level "+d.level+(d.school?" "+d.school:""));
  const bits = [lvl];
  if(d.time)       bits.push("Cast: "+d.time);
  if(d.range)      bits.push("Range: "+d.range);
  if(d.components) bits.push(d.components.split("").join(","));
  if(d.duration)   bits.push(d.duration);
  if(d.ritual)     bits.push("Ritual");
  if(d.conc)       bits.push("Concentration");
